            <div class="night-butterfly butterfly-2"></div>
            <div class="night-butterfly butterfly-3"></div>
            <div class="night-butterfly butterfly-4"></div>
        </div>

        <!-- 调用挂载在 window 上的全局方法 -->
        <div class="celestial-container" onclick="window.toggleYamatoTheme()" title="点击切换昼夜">
            <div class="sun"></div>
            <div class="moon"></div>
            <div class="chapter-num">$1</div>
        </div>

