    <script>
        (function() {
            // 读取浏览器本地保存的主题记忆，没有则默认白天
            const savedTheme = localStorage.getItem('yamatoThemeState') || 'day';

            // 将切换逻辑注册为全局函数，避免多条消息产生冲突
            if (typeof window.toggleYamatoTheme !== 'function') {
                window.toggleYamatoTheme = function() {
                    const currentState = localStorage.getItem('yamatoThemeState') || 'day';
                    const newState = currentState === 'day' ? 'night' : 'day';

                    // 记录新的状态到本地
                    localStorage.setItem('yamatoThemeState', newState);

                    // 遍历页面里出现过的所有组件，让它们同时切换
                    document.querySelectorAll('.yamato-container').forEach(container => {
                        if (newState === 'night') {
                            container.classList.add('night');
                        } else {
                            container.classList.remove('night');
                        }
                    });
                };
            }

            // 在每次生成新消息时，主动对齐当前页面上所有组件的主题状态
            document.querySelectorAll('.yamato-container').forEach(container => {
                if (savedTheme === 'night') {
                    container.classList.add('night');
                } else {
                    container.classList.remove('night');
                }
            });
        })();
    </script>
</body>
</html>
