(function () {
  var THEME_KEY = 'yu-choices-theme-dark';

  function readStoredTheme() {
    try {
      var hostWindow = window.parent || window;
      return hostWindow.localStorage.getItem(THEME_KEY) === 'true';
    } catch (e) {
      try {
        return localStorage.getItem(THEME_KEY) === 'true';
      } catch (err) {
        return false;
      }
    }
  }

  function saveStoredTheme(isDark) {
    try {
      var hostWindow = window.parent || window;
      hostWindow.localStorage.setItem(THEME_KEY, String(isDark));
      return;
    } catch (e) {}

    try {
      localStorage.setItem(THEME_KEY, String(isDark));
    } catch (e) {}
  }

  function applyTheme(root, isDark) {
    if (!root) return;

    root.classList.toggle('yu-dark-mode', isDark);

    var button = root.querySelector('.yu-theme-toggle');
    if (!button) return;

    button.textContent = isDark ? '☀' : '☾';
    button.title = isDark ? '切换为日间模式' : '切换为夜间模式';
    button.setAttribute('aria-label', button.title);
  }

  function initializeThemes() {
    var roots = document.querySelectorAll('.yu-choices-root:not(.yu-theme-ready)');
    var isDark = readStoredTheme();

    for (var i = 0; i < roots.length; i++) {
      applyTheme(roots[i], isDark);
      roots[i].classList.add('yu-theme-ready');
    }
  }

  window.toggleYuChoicesTheme = function (event, button) {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }

    if (!button) return;

    var root = button.closest('.yu-choices-root');
    if (!root) return;

    var isDark = !root.classList.contains('yu-dark-mode');
    saveStoredTheme(isDark);

    var roots = document.querySelectorAll('.yu-choices-root');
    for (var i = 0; i < roots.length; i++) {
      applyTheme(roots[i], isDark);
    }
  };

  window.handleYuChoiceKey = function (event, element) {
    if (!event || !element) return;

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      window.selectYuChoiceOption(element);
    }
  };

  window.selectYuChoiceOption = function (element) {
    if (!element) return;

    var root = element.closest('.yu-choices-root');
    if (!root) return;

    var rows = root.querySelectorAll('.yu-option-row');
    for (var i = 0; i < rows.length; i++) {
      rows[i].classList.remove('yu-selected');
      rows[i].setAttribute('aria-pressed', 'false');
    }

    element.classList.add('yu-selected');
    element.setAttribute('aria-pressed', 'true');

    var textElement = element.querySelector('.yu-option-text');
    var cleanText = textElement
      ? (textElement.innerText || textElement.textContent || '').trim()
      : '';

    if (!cleanText) return;

    try {
      var stWindow = window.parent || window;
      var context = stWindow.SillyTavern && typeof stWindow.SillyTavern.getContext === 'function'
        ? stWindow.SillyTavern.getContext()
        : null;

      if (context && typeof context.setInput === 'function') {
        context.setInput(cleanText);
        return;
      }
    } catch (e) {}

    try {
      var slash = (window.parent && window.parent.triggerSlash) || window.triggerSlash;
      if (typeof slash === 'function') {
        slash('/setinput ' + cleanText);
        return;
      }
    } catch (e) {}

    try {
      var parentDocument = window.parent && window.parent.document
        ? window.parent.document
        : document;

      var textarea = parentDocument.getElementById('send_textarea')
        || document.getElementById('send_textarea');

      if (textarea) {
        textarea.value = cleanText;
        textarea.dispatchEvent(new Event('input', { bubbles: true }));
        textarea.focus();
        return;
      }
    } catch (e) {}

    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(cleanText);
      }
    } catch (e) {}
  };

  initializeThemes();
  setTimeout(initializeThemes, 0);
  setTimeout(initializeThemes, 120);
})();
</script>
