/* =============================================================================
 *  Yu 推理格式 · 原生推理（Reasoning Formatting）自动应用脚本  v1.1.1
 *  适配：酒馆助手 / JS-Slash-Runner  +  SillyTavern 1.13.x 及以上
 *        （即「高级格式化 → 推理 → 推理内容格式化」存在 /reasoning-template 的版本）
 * -----------------------------------------------------------------------------
 *  v1.1.1 改动（按用户需求）：
 *    1. 预设名匹配改为 startsWith ['YU']：YU_V1.4.4 / YU_V1.5 / yu-xxx 都能命中。
 *    2. 关闭 require_api_match：自定义 OpenAI 兼容端点不再被 API 比较拦下。
 *    3. 关闭 restore_on_leave：离开预设/切 API 都不会自动还原推理设置。
 *    4. syncNow 删掉「API 不匹配还原」「离开预设还原」两段；手动还原按钮仍保留。
 *    5. getSelectedPresetName 在指定 api_id 读不到名字时，用不带参的管理器兜底。
 * -----------------------------------------------------------------------------
 *  它做什么：
 *    1. 监视当前聊天补全预设名；当预设名以 YU 开头时，自动切进本脚本管理的推理格式。
 *    2. 在【高级格式化 → 推理 → 推理内容格式化】里创建（或复用）名为「Yu」的格式预设：
 *         前缀 <thinking>    后缀 </thinking>    分隔符 \n
 *       并让它成为当前选中的格式（等价于执行 /reasoning-template Yu）。
 *    3. 勾选【推理】里的「自动解析」(auto_parse)：酒馆会在流式生成时就把
 *         <thinking>…</thinking> 拆进原生推理块（显示层是收起的 details），
 *       不再把标签当正文显示。
 *    4. 兜底一：对聊天里已经存在的楼层，只要 <thinking> 与 </thinking> 成对，
 *       也会被补折叠进推理块（不会误伤不成对的半截标签）。
 *    5. 兜底二：自定义正则扫描。给 <thinking> 之外的变体标签（如 ECoT、<thought>）
 *       追加规则，命中片段同样搬进推理块；规则可在脚本里改。
 *    6. 不再自动还原；只有手动点「还原推理设置」才会还原。
 * -----------------------------------------------------------------------------
 *  安装：酒馆助手 → 脚本库 → 新建脚本 → 把本文件内容整段粘进去 → 保存并启用。
 *  脚本按钮：应用Yu推理格式 / 扫描折叠 / 正则设置 / 还原推理设置。
 *  调试：把下面 CONFIG.debug 改成 true，在控制台看 [Yu推理格式] 日志；
 *        也可以在控制台调 YuReasoning.apply() / .scan() / .restore()。
 * ========================================================================== */

(() => {
  'use strict';

  // =========================== 1. 用户配置 ===========================

  const CONFIG = {
    // —— 触发条件 ——
    /** 当前聊天补全预设名（不区分大小写）。配合 preset_match: 'startsWith'，YU_V1.4.4 也能命中 */
    preset_names: ['YU'], // ★ 修改：适配 YU_V1.4.4 这类带版本号的预设名
    /** 预设名匹配方式：'exact' 完全一致 / 'contains' 包含 / 'startsWith' 开头是 */
    preset_match: 'startsWith', // ★ 修改：原为 'exact'
    /** 预设所属 API；仅作为“首选读取渠道”，不再参与是否触发的判断 */
    api_id: 'openai',
    /** ★ 修改：关闭 API 比较，避免自定义 OpenAI 兼容端点被误拦 */
    require_api_match: false,

    // —— 要创建 / 使用的推理格式预设 ——
    /** 在「推理内容格式化」里创建 / 使用的预设名（与聊天预设名无关） */
    template_name: 'Yu',
    /** 推理前缀 */
    prefix: '<thinking>',
    /** 推理后缀 */
    suffix: '</thinking>',
    /** 推理块与正文之间的分隔符 */
    separator: '\n',
    /** 同名预设已存在、但前后缀不一致时，是否覆盖成上面的配置 */
    overwrite_template: true,

    // —— 推理开关（这几个不属于格式预设本身，要单独写进 power_user.reasoning）——
    /** 勾选「自动解析」 */
    auto_parse: true,
    /** 推理块是否默认展开；false = 默认收起来 */
    auto_expand: false,
    /** 「显示隐藏推理」；null = 不改动 */
    show_hidden: null,

    // —— 自定义正则扫描（处理 <thinking> 之外的变体标签）——
    /** 是否启用正则扫描 */
    scan_enabled: true,
    /**
     * 内置规则，每行一条：名称 = /正则/gi
     * 有捕获组时取第 1 组，没有捕获组时取整个匹配；# 开头的行会被忽略。
     */
    scan_rules: [
      'thinking = /<(?:thinking|think|thought)>([\\s\\S]*?)<\\/(?:thinking|think|thought)>/gi',
      'ECoT = /<ECoT>([\\s\\S]*?)<\\/ECoT>/gi',
    ],
    /** 新消息到达 / 滑动后自动扫描一次 */
    scan_on_message: true,
    /** 正则扫描只在 Yu 预设下生效 */
    scan_only_under_yu: true,
    /** 楼层已有推理块时，把新扫到的内容接在后面；false = 直接跳过该楼层 */
    scan_append_to_existing: true,

    // —— 行为 ——
    /** 应用时，把已有楼层里成对/命中规则的标签也收进推理块 */
    fold_existing_on_apply: true,
    /** ★ 修改：关闭「离开 Yu 预设自动还原」，避免切预设/切 API 时被动改推理设置 */
    restore_on_leave: false,
    /** 兜底轮询间隔（毫秒，事件漏发时用）；0 = 关闭 */
    poll_interval_ms: 2000,

    /** 控制台调试日志 */
    debug: false,
  };

  const VERSION = '1.1.1';
  const LOG_TAG = '[Yu推理格式]';
  const BACKUP_KEY = 'yu_reasoning_backup';
  const SCAN_RULES_KEY = 'yu_reasoning_scan_rules';

  // =========================== 2. 基础小工具 ===========================

  /** 本脚本在脚本库里的名字（不在脚本环境时用默认名） */
  let scriptTitle = 'Yu推理格式';
  try {
    if (typeof getScriptName === 'function') scriptTitle = getScriptName() || scriptTitle;
  } catch (_) { /* 忽略：不在脚本环境 */ }

  const hasFn = (obj, key) => !!obj && typeof obj[key] === 'function';
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const debug = (...args) => { if (CONFIG.debug) console.log(LOG_TAG, ...args); };
  const warn = (...args) => console.warn(LOG_TAG, ...args);

  /** 取酒馆给的接口对象 */
  function getST() {
    return window.SillyTavern || null;
  }

  /** toastr 在脚本 iframe 里可能不是 window 属性，两个位置都试 */
  function getToastr() {
    try {
      if (typeof toastr !== 'undefined' && toastr) return toastr;
    } catch (_) { /* 忽略 */ }
    return window.toastr || null;
  }

  function toast(kind, message) {
    const t = getToastr();
    const fn = t && typeof t[kind] === 'function' ? t[kind] : (t && t.info);
    if (typeof fn === 'function') {
      try { fn.call(t, message, scriptTitle); return; } catch (_) { /* 忽略 */ }
    }
    debug('toast:', kind, message);
  }

  /** 把字符串转成可安全塞进正则的形式 */
  const escapeRegex = (text) => String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  /** tavern_events 可能是 iframe 全局，也可能是 window 属性 */
  function getTavernEvents() {
    try {
      if (typeof tavern_events !== 'undefined' && tavern_events) return tavern_events;
    } catch (_) { /* 忽略 */ }
    return window.tavern_events || {};
  }

  // =========================== 3. 读取 / 写入推理设置 ===========================

  /**
   * power_user.reasoning —— 酒馆「高级格式化 → 推理」的全部开关都在这里。
   * 结构（ST 1.13.x）：
   *   { name, prefix, suffix, separator, auto_parse, auto_expand,
   *     show_hidden, add_to_prompts, max_additions }
   */
  function getReasoningState() {
    const st = getST();
    const powerUser = st && st.powerUserSettings;
    if (!powerUser) return null;

    if (!powerUser.reasoning || typeof powerUser.reasoning !== 'object') {
      powerUser.reasoning = {
        name: '',
        auto_parse: false,
        add_to_prompts: false,
        auto_expand: false,
        show_hidden: false,
        prefix: '<think>',
        suffix: '</think>',
        separator: '\n',
        max_additions: 1,
      };
    }
    return powerUser.reasoning;
  }

  function snapshotReasoning() {
    const r = getReasoningState();
    if (!r) return null;
    return {
      name: String(r.name == null ? '' : r.name),
      prefix: String(r.prefix == null ? '' : r.prefix),
      suffix: String(r.suffix == null ? '' : r.suffix),
      separator: String(r.separator == null ? '' : r.separator),
      auto_parse: !!r.auto_parse,
      auto_expand: !!r.auto_expand,
      show_hidden: !!r.show_hidden,
    };
  }

  /** 备份存在脚本变量里，这样刷新页面后仍然知道「原本的推理设置」是什么 */
  function readBackup() {
    if (typeof getVariables !== 'function') return null;
    try {
      const vars = getVariables({ type: 'script' });
      const backup = vars && vars[BACKUP_KEY];
      return backup && typeof backup === 'object' ? backup : null;
    } catch (error) {
      debug('读取备份失败', error);
      return null;
    }
  }

  function writeBackup(backup) {
    if (typeof insertOrAssignVariables !== 'function') return;
    try {
      insertOrAssignVariables({ [BACKUP_KEY]: backup || null }, { type: 'script' });
    } catch (error) {
      debug('写入备份失败', error);
    }
  }

  // =========================== 4. 预设 / 格式预设 ===========================

  function getPresetManager(apiId) {
    const st = getST();
    if (!hasFn(st, 'getPresetManager')) return null;
    try {
      return st.getPresetManager(apiId) || null;
    } catch (_) {
      return null;
    }
  }

  function getMainApi() {
    const st = getST();
    if (!st) return '';
    if (st.mainApi) return String(st.mainApi);
    try {
      const ctx = typeof st.getContext === 'function' ? st.getContext() : null;
      return ctx && ctx.mainApi ? String(ctx.mainApi) : '';
    } catch (_) {
      return '';
    }
  }

  /**
   * 当前预设名（优先问预设管理器，其次回退到 oai_settings）。
   * ★ 修改：指定 api_id 的管理器读不到时，再用不带参的管理器兜底
   *   （ST 不传参时按当前 mainApi 自动选管理器，自定义 OpenAI 兼容也能拿到名字）。
   */
  function getSelectedPresetName(apiId) {
    let pm = getPresetManager(apiId);
    if (!pm && apiId) pm = getPresetManager(); // ★ 修改：不带参兜底

    if (hasFn(pm, 'getSelectedPresetName')) {
      try {
        const name = pm.getSelectedPresetName();
        if (name) return String(name);
      } catch (_) { /* 忽略 */ }
    }

    // 如果指定 api_id 读不到名字，再试一次不带参的管理器
    if (apiId) { // ★ 修改
      const fallback = getPresetManager();
      if (fallback && fallback !== pm && hasFn(fallback, 'getSelectedPresetName')) {
        try {
          const name = fallback.getSelectedPresetName();
          if (name) return String(name);
        } catch (_) { /* 忽略 */ }
      }
    }

    try {
      const st = getST();
      const settings = st && st.chatCompletionSettings;
      const name = settings && (settings.preset_settings_openai || settings.preset);
      if (name) return String(name);
    } catch (_) { /* 忽略 */ }
    return '';
  }

  /** 最后手段：借 STScript 的 /preset 拿当前预设名 */
  async function getSelectedPresetNameByCommand() {
    const st = getST();
    if (!hasFn(st, 'executeSlashCommandsWithOptions')) return '';
    try {
      const result = await st.executeSlashCommandsWithOptions('/preset');
      return String((result && result.pipe) || '').trim();
    } catch (_) {
      return '';
    }
  }

  const normalizeName = (name) => String(name == null ? '' : name).trim().toLowerCase();

  function isYuPreset(name) {
    const current = normalizeName(name);
    if (!current) return false;

    return CONFIG.preset_names.some((pattern) => {
      const wanted = normalizeName(pattern);
      if (!wanted) return false;
      switch (CONFIG.preset_match) {
        case 'contains': return current.includes(wanted);
        case 'startsWith': return current.startsWith(wanted);
        default: return current === wanted;
      }
    });
  }

  /** 现在这一刻，Yu 预设是不是在生效 */
  function isYuActiveNow() {
    // ★ 修改：require_api_match 默认 false，这里只在开启时才比较 API
    if (CONFIG.require_api_match) {
      const api = getMainApi();
      if (api && api !== CONFIG.api_id) return false;
    }
    return isYuPreset(getSelectedPresetName(CONFIG.api_id));
  }

  /** 推理格式预设的内容（与 ST 的 PresetManager.isPossiblyReasoningData 对齐） */
  function buildTemplate() {
    return {
      name: CONFIG.template_name,
      prefix: CONFIG.prefix,
      suffix: CONFIG.suffix,
      separator: CONFIG.separator,
    };
  }

  function templateMatches(template) {
    if (!template || typeof template !== 'object') return false;
    return String(template.prefix == null ? '' : template.prefix) === CONFIG.prefix
      && String(template.suffix == null ? '' : template.suffix) === CONFIG.suffix
      && String(template.separator == null ? '' : template.separator) === CONFIG.separator;
  }

  /**
   * 保证「推理内容格式化」里存在名为 template_name 的预设，并把它设为当前格式。
   *
   * 走 ST 官方通道：SillyTavern.getPresetManager('reasoning')
   *   → savePreset(name, {name, prefix, suffix, separator})   创建 / 覆盖
   *   → 内部会 POST /api/presets/save { apiId: 'reasoning' }   落盘
   *   → updateList() 选中该 option 并触发 change
   *   → ST 原生 change 处理器把 name / prefix / suffix / separator 写进 power_user.reasoning
   *
   * @returns {'created'|'selected'|'local'|'none'}
   */
  async function ensureReasoningTemplate() {
    const state = getReasoningState();
    if (!state) return 'none';

    const pm = getPresetManager('reasoning');

    if (pm && hasFn(pm, 'savePreset') && hasFn(pm, 'getAllPresets')) {
      try {
        const names = pm.getAllPresets() || [];
        const exists = names.some((name) => String(name) === CONFIG.template_name);

        let current = null;
        if (exists && hasFn(pm, 'getCompletionPresetByName')) {
          try { current = pm.getCompletionPresetByName(CONFIG.template_name); } catch (_) { current = null; }
        }

        // ① 没有 → 新建
        if (!exists) {
          await pm.savePreset(CONFIG.template_name, buildTemplate());
          toast('success', `已创建推理格式预设「${CONFIG.template_name}」`);
          return 'created';
        }

        // ② 有但对不上 → 覆盖（可在 CONFIG 里关掉）
        if (!templateMatches(current) && CONFIG.overwrite_template) {
          await pm.savePreset(CONFIG.template_name, buildTemplate());
          debug('已按配置覆盖同名推理格式预设', current);
          return 'created';
        }

        // ③ 有且一致 → 直接选中它（触发 ST 原生 change，前缀/后缀自动写入）
        const value = hasFn(pm, 'findPreset') ? pm.findPreset(CONFIG.template_name) : CONFIG.template_name;
        if (value !== undefined && value !== null && hasFn(pm, 'selectPreset')) {
          pm.selectPreset(value);
        }
        return 'selected';
      } catch (error) {
        warn('通过预设管理器创建 / 选择推理格式失败，改为直接写 power_user.reasoning', error);
      }
    }

    // 兜底：老版本酒馆没有「推理内容格式化」预设管理器，只写字段
    state.name = CONFIG.template_name;
    state.prefix = CONFIG.prefix;
    state.suffix = CONFIG.suffix;
    state.separator = CONFIG.separator;
    debug('当前酒馆没有 reasoning 预设管理器，已直接写入 power_user.reasoning');
    return 'local';
  }

  // =========================== 5. 同步 ST 原生界面 ===========================

  /** 把 power_user.reasoning 的现状回写到「高级格式化 → 推理」面板，避免面板显示与实际不一致 */
  function syncReasoningUi() {
    const state = getReasoningState();
    if (!state) return;

    let doc = null;
    try {
      doc = (window.parent && window.parent.document) || document;
    } catch (_) {
      doc = null;
    }
    if (!doc) return;

    const setChecked = (selector, value) => {
      const el = doc.querySelector(selector);
      if (el && 'checked' in el) el.checked = !!value;
    };
    const setValue = (selector, value) => {
      const el = doc.querySelector(selector);
      if (el && 'value' in el) el.value = String(value == null ? '' : value);
    };

    setChecked('#reasoning_auto_parse', state.auto_parse);
    setChecked('#reasoning_auto_expand', state.auto_expand);
    if (typeof state.show_hidden === 'boolean') setChecked('#reasoning_show_hidden', state.show_hidden);

    setValue('#reasoning_prefix', state.prefix);
    setValue('#reasoning_suffix', state.suffix);
    setValue('#reasoning_separator', state.separator);

    // 下拉框指到当前模板（直接改 value，不触发 change，避免重复保存）
    const select = doc.querySelector('#reasoning_select');
    if (select && state.name) {
      const options = Array.prototype.slice.call(select.options || []);
      const hit = options.find((opt) => opt.value === state.name || opt.textContent === state.name);
      if (hit) select.value = hit.value;
    }
  }

  // =========================== 6. 推理格式的拼装 / 解析 ===========================

  /** 当前生效的推理格式，优先取 ST 里的实时值 */
  function currentFormat() {
    const state = getReasoningState();
    return {
      prefix: String((state && state.prefix) || CONFIG.prefix),
      suffix: String((state && state.suffix) || CONFIG.suffix),
      separator: String(state && state.separator != null ? state.separator : CONFIG.separator),
    };
  }

  /**
   * applyFormatter：把「推理 + 正文」拼成一条带前后缀的完整消息。
   * 等价于 ST 内部的 formatReasoning(reasoning, content).formatted：
   *     `${prefix}${reasoning}${suffix}${separator}${content}`
   */
  function applyFormatter(reasoning, content = '', format = currentFormat()) {
    const body = String(reasoning == null ? '' : reasoning).trim();
    const tail = String(content == null ? '' : content);
    if (!body) return tail;
    return `${format.prefix}${body}${format.suffix}${format.separator}${tail}`;
  }

  /**
   * parseFormatter：把一条消息拆成 [推理块, 正文]。
   * 只有前后缀**成对出现**时才算推理；半截标签原样保留。
   */
  function parseFormatter(text, format = currentFormat()) {
    const raw = String(text == null ? '' : text);
    const prefix = format.prefix;
    const suffix = format.suffix;
    if (!prefix || !suffix) return { reasoning: '', content: raw };

    const regex = new RegExp(`${escapeRegex(prefix)}([\\s\\S]*?)${escapeRegex(suffix)}`);
    const matched = raw.match(regex);
    if (!matched) return { reasoning: '', content: raw };

    const reasoning = matched[1].trim();
    const content = (raw.slice(0, matched.index) + raw.slice(matched.index + matched[0].length)).trim();
    return { reasoning, content };
  }

  // =========================== 7. 折叠（把成对标签收进推理块） ===========================

  function refreshMessage(id) {
    const st = getST();
    const message = st && st.chat && st.chat[id];
    if (!message) return;
    try {
      if (hasFn(st, 'updateMessageBlock')) st.updateMessageBlock(id, message);
      if (hasFn(st, 'updateReasoningUI')) st.updateReasoningUI(id);
    } catch (error) {
      debug(`刷新第 ${id} 楼失败`, error);
    }
  }

  /**
   * 把聊天里所有「<thinking>…</thinking> 成对出现」的楼层折叠成原生推理块。
   *
   * @returns {Promise<number>} 被折叠的楼层数
   */
  async function foldPairedReasoning({ silent = false } = {}) {
    const st = getST();
    const chat = st && st.chat;
    if (!Array.isArray(chat)) return 0;

    const format = { prefix: CONFIG.prefix, suffix: CONFIG.suffix, separator: CONFIG.separator };
    if (!format.prefix || !format.suffix) return 0;

    const foldedIds = [];

    for (let id = 0; id < chat.length; id++) {
      const message = chat[id];
      if (!message || message.is_user || message.is_system) continue;

      const text = String(message.mes == null ? '' : message.mes);
      if (!text.includes(format.prefix) || !text.includes(format.suffix)) continue;
      if (message.extra && message.extra.reasoning) continue;

      const parsed = parseFormatter(text, format);
      if (!parsed.reasoning) continue;

      if (!message.extra || typeof message.extra !== 'object') message.extra = {};
      message.extra.reasoning = parsed.reasoning;
      message.extra.reasoning_type = 'parsed';
      message.mes = parsed.content;

      foldedIds.push(id);
    }

    if (foldedIds.length === 0) {
      if (!silent) debug('没有找到可折叠的成对标签');
      return 0;
    }

    for (const id of foldedIds) refreshMessage(id);

    try {
      if (hasFn(st, 'saveChat')) await st.saveChat();
      else if (hasFn(st, 'saveChatConditional')) await st.saveChatConditional();
    } catch (error) {
      warn('保存聊天失败，折叠结果可能不会落盘', error);
    }

    debug('已折叠楼层', foldedIds);
    return foldedIds.length;
  }

  // =========================== 8. 自定义正则扫描（可选） ===========================

  function buildRegex(source) {
    const text = String(source == null ? '' : source).trim();
    const literal = text.match(/^\/([\s\S]+)\/([a-z]*)$/i);
    const body = literal ? literal[1] : text;
    let flags = literal ? literal[2] : 'g';
    if (!flags.includes('g')) flags += 'g';
    return new RegExp(body, flags);
  }

  let scanRuleCache = { text: null, rules: [] };

  function getScanRulesText() {
    try {
      if (typeof getVariables === 'function') {
        const vars = getVariables({ type: 'script' });
        const saved = vars && vars[SCAN_RULES_KEY];
        if (typeof saved === 'string' && saved.trim()) return saved;
      }
    } catch (error) {
      debug('读取自定义正则失败，改用内置规则', error);
    }
    return CONFIG.scan_rules.join('\n');
  }

  function saveScanRulesText(text) {
    if (typeof insertOrAssignVariables !== 'function') return false;
    try {
      insertOrAssignVariables({ [SCAN_RULES_KEY]: String(text) }, { type: 'script' });
      scanRuleCache = { text: null, rules: [] };
      return true;
    } catch (error) {
      warn('保存自定义正则失败', error);
      return false;
    }
  }

  function getScanRules() {
    const text = getScanRulesText();
    if (scanRuleCache.text === text) return scanRuleCache.rules;

    const rules = [];
    for (const line of text.split(/\r?\n/)) {
      const raw = line.trim();
      if (!raw || raw.startsWith('#')) continue;

      const eq = raw.indexOf('=');
      const name = (eq >= 0 ? raw.slice(0, eq) : '规则').trim() || '规则';
      const source = (eq >= 0 ? raw.slice(eq + 1) : raw).trim();
      if (!source) continue;

      try {
        rules.push({ name, regex: buildRegex(source) });
      } catch (error) {
        warn(`自定义正则「${name}」语法错误，已跳过：${error.message}`);
      }
    }

    scanRuleCache = { text, rules };
    return rules;
  }

  async function scanMessage(id, { save = true } = {}) {
    const st = getST();
    const message = st && st.chat && st.chat[id];
    if (!message || message.is_user || message.is_system) return false;

    const original = String(message.mes == null ? '' : message.mes);
    if (!original) return false;

    const rules = getScanRules();
    if (rules.length === 0) return false;

    const collected = [];
    let text = original;

    for (const rule of rules) {
      text = text.replace(rule.regex, (match, ...rest) => {
        const captured = typeof rest[0] === 'string' ? rest[0] : match;
        const piece = String(captured == null ? '' : captured).trim();
        if (piece) collected.push(piece);
        return '';
      });
    }

    if (collected.length === 0) return false;

    if (!message.extra || typeof message.extra !== 'object') message.extra = {};

    const existing = String(message.extra.reasoning == null ? '' : message.extra.reasoning).trim();
    if (existing && !CONFIG.scan_append_to_existing) return false;

    message.extra.reasoning = existing
      ? `${existing}\n\n${collected.join('\n\n')}`
      : collected.join('\n\n');
    message.extra.reasoning_type = 'parsed';
    message.mes = text.trim();

    refreshMessage(id);

    if (save) {
      try {
        if (hasFn(st, 'saveChat')) await st.saveChat();
        else if (hasFn(st, 'saveChatConditional')) await st.saveChatConditional();
      } catch (error) {
        warn('保存聊天失败，扫描结果可能不会落盘', error);
      }
    }

    debug(`第 ${id} 楼正则扫描命中 ${collected.length} 段`);
    return true;
  }

  async function scanAllMessages({ silent = false } = {}) {
    const st = getST();
    const chat = st && st.chat;
    if (!Array.isArray(chat)) return 0;

    let changed = 0;
    for (let id = 0; id < chat.length; id++) {
      if (await scanMessage(id, { save: false })) changed++;
    }

    if (changed > 0) {
      try {
        if (hasFn(st, 'saveChat')) await st.saveChat();
        else if (hasFn(st, 'saveChatConditional')) await st.saveChatConditional();
      } catch (error) {
        warn('保存聊天失败，扫描结果可能不会落盘', error);
      }
    }

    if (!silent) debug(`正则扫描：改动 ${changed} 条楼层`);
    return changed;
  }

  async function sweepChat({ silent = false } = {}) {
    const folded = await foldPairedReasoning({ silent: true });
    const scanned = await scanAllMessages({ silent: true });
    const total = folded + scanned;
    debug('扫描完成', { folded, scanned });

    if (!silent) {
      toast(total > 0 ? 'success' : 'info',
        total > 0
          ? `已处理 ${total} 条楼层（原生 ${folded} / 正则 ${scanned}）`
          : '没有找到成对可收的推理标签');
    }
    return total;
  }

  async function openScanRuleEditor() {
    const st = getST();
    const current = getScanRulesText();
    const hint = '每行一条规则，格式：名称 = /正则/gi'
      + '\n有捕获组时取第 1 组，没有则取整个匹配；# 开头的行会被忽略。';

    let text = null;

    try {
      const popupType = st && st.POPUP_TYPE;
      if (hasFn(st, 'callGenericPopup') && popupType && typeof popupType.INPUT === 'number') {
        const result = await st.callGenericPopup(hint, popupType.INPUT, current, { rows: 10, wide: true });
        if (typeof result !== 'string') return;
        text = result;
      }
    } catch (error) {
      debug('原生输入弹窗不可用，改用 prompt', error);
    }

    if (text === null) {
      try { text = window.prompt(hint, current); } catch (_) { text = null; }
      if (typeof text !== 'string') return;
    }

    const lines = String(text).split(/\r?\n/);
    for (let index = 0; index < lines.length; index++) {
      const raw = lines[index].trim();
      if (!raw || raw.startsWith('#')) continue;

      const eq = raw.indexOf('=');
      const source = (eq >= 0 ? raw.slice(eq + 1) : raw).trim();
      if (!source) continue;

      try {
        buildRegex(source);
      } catch (error) {
        toast('error', `第 ${index + 1} 行正则语法错误：${error.message}`);
        return;
      }
    }

    if (!saveScanRulesText(text)) {
      toast('error', '规则保存失败');
      return;
    }

    const total = await sweepChat({ silent: true });
    toast('success', total > 0 ? `正则已保存，重扫了 ${total} 条楼层` : '正则已保存（现有楼层没有新的命中）');
  }

  // =========================== 9. 应用 / 还原 ===========================

  let applied = false;
  let applying = false;
  let lastPresetName = '';
  let queue = Promise.resolve();

  function enqueue(task) {
    queue = queue.then(task).catch((error) => warn('任务执行失败', error));
    return queue;
  }

  function isYuConfigReady() {
    const state = getReasoningState();
    if (!state) return false;
    return !!state.auto_parse === !!CONFIG.auto_parse
      && String(state.prefix) === CONFIG.prefix
      && String(state.suffix) === CONFIG.suffix;
  }

  /**
   * 让「Yu 推理格式」生效：
   *   创建 / 选中格式预设 → 勾选自动解析 → 保存设置 → 同步面板 → 补折叠旧楼层
   */
  async function applyYuReasoning(origin = 'manual') {
    if (applying) return false;

    const state = getReasoningState();
    if (!state) {
      warn('拿不到 power_user.reasoning，当前酒馆版本可能不支持推理格式设置');
      return false;
    }

    applying = true;
    try {
      if (!readBackup()) {
        const backup = snapshotReasoning();
        if (backup) writeBackup(backup);
      }

      await ensureReasoningTemplate();

      if (String(state.prefix) !== CONFIG.prefix || String(state.suffix) !== CONFIG.suffix) {
        state.name = CONFIG.template_name;
        state.prefix = CONFIG.prefix;
        state.suffix = CONFIG.suffix;
        state.separator = CONFIG.separator;
      }

      state.auto_parse = !!CONFIG.auto_parse;
      state.auto_expand = !!CONFIG.auto_expand;
      if (typeof CONFIG.show_hidden === 'boolean') state.show_hidden = CONFIG.show_hidden;

      try {
        const st = getST();
        if (hasFn(st, 'saveSettingsDebounced')) await st.saveSettingsDebounced();
      } catch (error) {
        warn('保存设置失败', error);
      }

      syncReasoningUi();
      applied = true;
      debug('已应用 Yu 推理格式', { origin, state: snapshotReasoning() });

      if (origin !== 'poll') {
        toast('success', `推理格式已切到「${CONFIG.template_name}」：${CONFIG.prefix} … ${CONFIG.suffix}，自动解析已开启`);
      }

      if (CONFIG.fold_existing_on_apply) {
        const total = await sweepChat({ silent: true });
        if (total > 0) toast('info', `另外把 ${total} 条楼层里成对的推理标签收进了推理块`);
      }

      return true;
    } finally {
      applying = false;
    }
  }

  /**
   * 手动还原：把用户原本的推理设置写回去。
   * 只在「当前设置仍然是脚本写进去的那一套」时才还原，不会覆盖用户手动改动。
   * ★ 修改：只由手动按钮 / 控制台 API 触发，syncNow 不再调用它。
   */
  async function restoreReasoning(origin = 'manual') {
    const state = getReasoningState();
    const backup = readBackup();
    if (!state || !backup) return false;

    const stillOurs = String(state.prefix) === CONFIG.prefix && String(state.suffix) === CONFIG.suffix;
    if (!stillOurs) {
      debug('当前推理设置已被手动修改，跳过还原');
      writeBackup(null);
      applied = false;
      return false;
    }

    let restoredByPreset = false;
    const pm = getPresetManager('reasoning');
    if (pm && backup.name && hasFn(pm, 'getAllPresets')) {
      try {
        const names = pm.getAllPresets() || [];
        if (names.some((name) => String(name) === String(backup.name))) {
          const value = hasFn(pm, 'findPreset') ? pm.findPreset(backup.name) : backup.name;
          if (value !== undefined && value !== null && hasFn(pm, 'selectPreset')) {
            pm.selectPreset(value);
            restoredByPreset = true;
          }
        }
      } catch (error) {
        debug('切回原推理格式预设失败', error);
      }
    }

    if (!restoredByPreset) {
      state.name = backup.name;
      state.prefix = backup.prefix;
      state.suffix = backup.suffix;
      state.separator = backup.separator;
    }

    state.auto_parse = !!backup.auto_parse;
    state.auto_expand = !!backup.auto_expand;
    if (typeof backup.show_hidden === 'boolean') state.show_hidden = backup.show_hidden;

    try {
      const st = getST();
      if (hasFn(st, 'saveSettingsDebounced')) await st.saveSettingsDebounced();
    } catch (error) {
      warn('保存设置失败', error);
    }

    syncReasoningUi();
    writeBackup(null);
    applied = false;
    debug('已还原推理设置', { origin, state: snapshotReasoning() });

    if (origin !== 'poll') toast('info', '已还原原本的推理格式设置');
    return true;
  }

  // =========================== 10. 同步总入口 ===========================

  /**
   * ★ 修改：只认预设名。
   *   - 不再比较 API；
   *   - 不是 Yu 预设就什么都不做（不 apply，也不还原）；
   *   - 手动还原按钮仍然可用。
   */
  async function syncNow(origin = 'manual') {
    if (!getST()) return;

    let name = getSelectedPresetName(CONFIG.api_id);
    if (!name) name = await getSelectedPresetNameByCommand();
    lastPresetName = name;

    if (!isYuPreset(name)) return;

    if (!applied || !isYuConfigReady()) await applyYuReasoning(origin);
  }

  // =========================== 11. 事件 / 按钮 / 轮询 ===========================

  function setupButtons() {
    const buttons = [
      { name: '应用Yu推理格式', visible: true },
      { name: '扫描折叠', visible: true },
      { name: '正则设置', visible: true },
      { name: '还原推理设置', visible: true },
    ];

    try {
      if (typeof replaceScriptButtons === 'function') replaceScriptButtons(buttons);
    } catch (error) {
      debug('设置脚本按钮失败（可能不在脚本环境）', error);
    }

    const bind = (buttonName, handler) => {
      try {
        if (typeof getButtonEvent === 'function' && typeof eventOn === 'function') {
          eventOn(getButtonEvent(buttonName), () => { enqueue(handler); });
        }
      } catch (error) {
        debug(`绑定按钮「${buttonName}」失败`, error);
      }
    };

    bind('应用Yu推理格式', () => applyYuReasoning('manual'));
    bind('扫描折叠', () => sweepChat());
    bind('正则设置', () => openScanRuleEditor());
    bind('还原推理设置', () => restoreReasoning('manual'));
  }

  function setupEvents() {
    const events = getTavernEvents();
    const watched = [
      [events.OAI_PRESET_CHANGED_AFTER, 'preset-changed'],
      [events.PRESET_CHANGED, 'preset-changed'],
      [events.MAIN_API_CHANGED, 'api-changed'],
      [events.SETTINGS_LOADED_AFTER, 'settings-loaded'],
      [events.CHAT_CHANGED, 'chat-changed'],
    ];

    for (const item of watched) {
      const eventType = item[0];
      const origin = item[1];
      if (!eventType || typeof eventOn !== 'function') continue;
      try {
        eventOn(eventType, () => { enqueue(() => syncNow(origin)); });
      } catch (error) {
        debug(`监听事件 ${eventType} 失败`, error);
      }
    }
  }

  function setupScanEvents() {
    if (!CONFIG.scan_enabled || !CONFIG.scan_on_message) return;
    if (typeof eventOn !== 'function') return;

    const events = getTavernEvents();
    const handler = (messageId) => {
      const id = Number(messageId);
      if (!Number.isInteger(id) || id < 0) return;

      enqueue(async () => {
        if (CONFIG.scan_only_under_yu && !isYuActiveNow()) return;
        await scanMessage(id);
      });
    };

    for (const eventType of [events.MESSAGE_RECEIVED, events.MESSAGE_SWIPED]) {
      if (!eventType) continue;
      try {
        eventOn(eventType, handler);
      } catch (error) {
        debug(`监听 ${eventType} 失败`, error);
      }
    }
  }

  let pollTimer = null;

  function startPolling() {
    const interval = Number(CONFIG.poll_interval_ms) || 0;
    if (interval <= 0 || pollTimer) return;

    pollTimer = setInterval(() => {
      const name = getSelectedPresetName(CONFIG.api_id);
      const changed = name !== lastPresetName;
      lastPresetName = name;

      if (changed || (isYuPreset(name) && !isYuConfigReady())) {
        enqueue(() => syncNow('poll'));
      }
    }, Math.max(1000, interval));
  }

  function stopPolling() {
    if (pollTimer) {
      clearInterval(pollTimer);
      pollTimer = null;
    }
  }

  // =========================== 12. 启动 ===========================

  async function waitForSillyTavern(timeoutMs = 15000) {
    const started = Date.now();
    while (Date.now() - started < timeoutMs) {
      if (getST()) return true;
      await sleep(150);
    }
    return false;
  }

  async function bootstrap() {
    if (!(await waitForSillyTavern())) {
      warn('等待 SillyTavern 接口超时，脚本未启动');
      return;
    }

    setupButtons();
    setupEvents();
    setupScanEvents();

    await enqueue(() => syncNow('startup'));
    startPolling();

    try {
      window.addEventListener('pagehide', stopPolling);
    } catch (_) { /* 忽略 */ }

    try {
      window.YuReasoning = {
        version: VERSION,
        config: CONFIG,
        apply: () => enqueue(() => applyYuReasoning('manual')),
        restore: () => enqueue(() => restoreReasoning('manual')),
        fold: () => foldPairedReasoning(),
        scan: () => scanAllMessages(),
        sweep: () => sweepChat(),
        editRules: () => openScanRuleEditor(),
        getRules: () => getScanRulesText(),
        sync: () => enqueue(() => syncNow('manual')),
        applyFormatter,
        parseFormatter,
        snapshot: () => snapshotReasoning(),
      };
    } catch (_) { /* 忽略 */ }

    console.info(LOG_TAG, `v${VERSION} 已加载`, {
      mainApi: getMainApi(),
      preset: getSelectedPresetName(CONFIG.api_id) || '(未取到)',
    });

    debug('初始化完成', {
      version: VERSION,
      mainApi: getMainApi(),
      preset: getSelectedPresetName(CONFIG.api_id),
      reasoning: snapshotReasoning(),
    });
  }

  bootstrap();
})();

