      const w = rootWin;
      if (w.SillyTavern && typeof w.SillyTavern.getContext === 'function') return w.SillyTavern.getContext();
      if (typeof SillyTavern !== 'undefined' && typeof SillyTavern.getContext === 'function') return SillyTavern.getContext();
    } catch (e) { /* ignore */ }
    return null;
  }

  function presetName() {
    try { return String(getLoadedPresetName() || ''); } catch (e) { return ''; }
  }

  function readPreset() {
    try { return getPreset('in_use'); } catch (e) { return null; }
  }

  /* ---------- 预设读取 ---------- */
  function bookOf(preset) {
    const t = preset && preset.extensions && preset.extensions.baibaiToolkit;
    const b = t && t.presetPromptGroups;
    if (!b || typeof b !== 'object') return null;
    if (!Array.isArray(b.groups)) b.groups = [];
    if (!b.prompts || typeof b.prompts !== 'object' || Array.isArray(b.prompts)) b.prompts = {};
    return b;
  }

  function promptKeys(p) {
    if (!p) return [];
    const extra = (p.extra && typeof p.extra === 'object') ? p.extra : {};
    const out = [];
    [p.identifier, p.id, extra['原标识'], extra.identifier, p.name].forEach(k => {
      if (k === undefined || k === null || k === '') return;
      const s = String(k);
      if (!out.includes(s)) out.push(s);
    });
    return out;
  }

  function groupIdOf(book, p) {
    if (!book) return '';
    const keys = promptKeys(p);
    for (let i = 0; i < keys.length; i += 1) {
      const meta = book.prompts[keys[i]];
      if (meta && meta.groupId) return String(meta.groupId);
    }
    return '';
  }

  function readVars(content, kind) {
    const out = [];
    if (typeof content !== 'string' || !content || content.indexOf(kind) < 0) return out;
    // 宽松匹配：作者偶尔会漏写结尾的 "::"（预设里「性向锁定-GB」就是 {{setvar::性向锁定 + 换行），
    // 所以 "::" / 换行 / 结尾 都算一个变量的结束。
    const re = new RegExp('\\{\\{\\s*' + kind + '\\s*::\\s*([^:{}]+?)\\s*(?:::|\\r?\\n|\\}|$)', 'gi');
    let hit;
    const seen = new Set();
    while ((hit = re.exec(content)) !== null) {
      const key = String(hit[1] || '').trim();
      if (key && !seen.has(key)) { seen.add(key); out.push(key); }
    }
    return out;
  }

  const isFenceName = n => /^[╭╰┌└]/.test(String(n || '').trim());

  function kindOf(p, name) {
    if (name === RESET_NAME) return 'locked';
    const ids = promptKeys(p).filter(k => PLACEHOLDER_IDS.has(k));
    if (ids.length) return 'placeholder';
    if (/^🐟💬/.test(name)) return 'note';
    if (/^🎀｜猜你想缝/.test(name)) return 'stitch';
    if (isFenceName(name) && String(p.content || '').length <= STRUCT_MAX) return 'struct';
    return 'toggle';
  }

  /* ---------- 纯计算：把预设变成可渲染的模型 ---------- */
  function buildModel(preset) {
    if (!preset || !Array.isArray(preset.prompts)) return null;
    const book = bookOf(preset);
    const groups = book ? book.groups.slice().sort((a, b) => (Number(a.order) || 0) - (Number(b.order) || 0)) : [];
    const groupName = new Map(groups.map(g => [String(g.id), String(g.name || '')]));

    const items = [];
    const byName = new Map();
    const byKey = new Map();
    preset.prompts.forEach((p, i) => {
      if (!p || !p.name) return;
      const name = String(p.name).trim();
      if (!name) return;
      // 同名条目在"五选一｜思维链"里很常见（开始thinking / 结束thinking），
      // 所以主键必须用稳定 id，不能用名字。
      const key = String(p.identifier || p.id || ('name:' + name));
      if (byKey.has(key)) return;
      const kind = kindOf(p, name);
      const gid = groupIdOf(book, p);
      const it = {
        index: i,
        key,
        prompt: p,
        name,
        kind,
        on: p.enabled !== false,
        contentLength: typeof p.content === 'string' ? p.content.length : 0,
        groupId: gid,
        group: groupName.get(gid) || '',
        set: readVars(p.content, 'setvar'),
        add: readVars(p.content, 'addvar'),
        radio: '',
        // 这三项是独立的正文段（注视 / 情感 / 保护），不是互斥的 setvar。
        multi: /^[⤷\s]*(凝user|爱user|嬷user)$/.test(name) ? 'user 塑造' : '',
      };
      items.push(it);
      byKey.set(key, it);
      if (!byName.has(name)) byName.set(name, it);
    });

    const bySet = new Map();
    const byAdd = new Map();
    const push = (m, k, it) => { if (!m.has(k)) m.set(k, []); m.get(k).push(it); };

    items.forEach(it => {
      if (it.kind !== 'toggle' && it.kind !== 'stitch') return;
      if (it.name === RESET_NAME) return;
      it.set.forEach(k => push(bySet, k, it));
      it.add.forEach(k => push(byAdd, k, it));
    });

    bySet.forEach((list, key) => {
      if (list.length < 2) return;
      list.forEach(it => { if (!it.radio) it.radio = 'var:' + key; });
    });
    byAdd.forEach((list, key) => {
      if (list.length < 2) return;
      list.forEach(it => { if (!it.multi) it.multi = 'var:' + key; });
    });

    MANUAL_RADIO.forEach(rule => {
      const members = items.filter(it => (it.kind === 'toggle' || it.kind === 'stitch') && rule.test(it.name));
      if (members.length < 2) return;
      members.forEach(it => { it.radio = 'ui:' + rule.key; });
    });

    const radioIndex = new Map();
    const multiIndex = new Map();
    items.forEach(it => {
      if (it.radio) { if (!radioIndex.has(it.radio)) radioIndex.set(it.radio, []); radioIndex.get(it.radio).push(it); }
      if (it.multi) { if (!multiIndex.has(it.multi)) multiIndex.set(it.multi, []); multiIndex.get(it.multi).push(it); }
    });

    return {
      book, groups, groupName, items, byName, byKey, radioIndex, multiIndex,
      presetName: presetName(),
      preset,
    };
  }

  function radioTitle(key) {
    if (key.indexOf('var:') === 0) {
      const k = key.slice(4);
      return KEY_LABEL[k] || k;
    }
    const rule = MANUAL_RADIO.find(r => 'ui:' + r.key === key);
    return rule ? rule.title : key;
  }

  function multiTitle(key) {
    const k = key.indexOf('var:') === 0 ? key.slice(4) : key;
    return ADD_LABEL[k] || k;
  }

  /* ---------- 状态与持久化 ---------- */
  const DEFAULT_STORE = { notes: true, stitch: false };

  function readGlobalStore() {
    try {
      const all = getVariables({ type: 'global' });
      const saved = all && all[STORE_KEY];
      if (saved && typeof saved === 'object') {
        return {
          notes: saved.notes !== false,
          stitch: saved.stitch === true,
        };
      }
    } catch (e) { /* ignore */ }
    return clone(DEFAULT_STORE);
  }

  let store = readGlobalStore();

  /* ---------- 写入 ---------- */
  let applying = false;
  let queue = Promise.resolve();
  let model = null;

  function enqueue(task) {
    queue = queue.then(task, task);
    return queue;
  }

  async function commitEnabled(pairs) {
    if (!pairs.length) return;
    const want = new Map(pairs.map(x => [String(x.key || x.name), !!x.on]));
    await updatePresetWith('in_use', preset => {
      (preset.prompts || []).forEach(p => {
        if (!p) return;
        const k = String(p.identifier || p.id || ('name:' + String(p.name || '')));
        if (want.has(k)) p.enabled = want.get(k);
      });
      return preset;
    }, { render: 'debounced' });
  }

  function writeBookInto(target, payload) {
    if (!target || typeof target !== 'object') return;
    try {
      if (!target.extensions || typeof target.extensions !== 'object') target.extensions = {};
      if (!target.extensions.baibaiToolkit || typeof target.extensions.baibaiToolkit !== 'object') target.extensions.baibaiToolkit = {};
      target.extensions.baibaiToolkit.presetPromptGroups = payload;
    } catch (e) { /* ignore */ }
  }

  function bookPayload(book) {
    if (!book) return null;
    return {
      version: typeof book.version === 'number' ? book.version : 1,
      groups: clone(book.groups || []),
      prompts: clone(book.prompts || {}),
    };
  }

  /* 柏宝箱用自己的运行时缓存画分组；只改预设不刷缓存，界面会不同步。 */
  function syncBookRuntime(book) {
    const payload = bookPayload(book);
    if (!payload) return;
    const w = rootWin;
    try {
      const inst = w.__baiBaiToolkitExtensionInstalled;
      if (inst && typeof inst === 'object') {
        inst.presetPromptGroupRuntimeState = payload;
        if (presetName()) inst.presetPromptGroupRuntimePresetName = presetName();
        delete inst.presetPromptGroupExtensionSyncKey;
        const mgr = inst.__baiBaiToolkitPresetVueListManager;
        if (mgr && typeof mgr === 'object') mgr.lastSyncSignature = '';
      }
    } catch (e) { /* ignore */ }
    try {
      const ctx = hostCtx();
      if (ctx) writeBookInto(ctx.chatCompletionSettings, payload);
    } catch (e) { /* ignore */ }
    try { writeBookInto(w.oai_settings, payload); } catch (e) { /* ignore */ }
    try {
      const svc = w.TavernHelper && w.TavernHelper.builtin && w.TavernHelper.builtin.promptManager
        && w.TavernHelper.builtin.promptManager.serviceSettings;
      writeBookInto(svc, payload);
    } catch (e) { /* ignore */ }
  }

  /* YU_GROUP_GATE_v1 */
  let localGate = null;
  function groupManager() {
    const ctx = hostCtx();
    return [rootWin.TavernHelper?.builtin?.promptManager,
      typeof builtin !== 'undefined' && builtin?.promptManager, ctx?.promptManager,
      typeof TavernHelper !== 'undefined' && TavernHelper?.builtin?.promptManager]
      .find(pm => typeof pm?.getPromptCollection === 'function' && typeof pm?.isPromptDisabledForActiveCharacter === 'function' && typeof pm?.getPromptOrderForCharacter === 'function');
  }
  function baiBaiActive() {
    const pm = groupManager();
    if (pm?.getPromptCollection?.__baiBaiToolkitOriginalGetPromptCollection && pm?.isPromptDisabledForActiveCharacter?.__baiBaiToolkitOriginalIsPromptDisabledForActiveCharacter) return true;
    const inst = rootWin.__baiBaiToolkitExtensionInstalled;
    if (!inst || typeof inst !== 'object') return false;
    return Object.values(inst).some(p => p?.manager && (!pm || p.manager === pm) && typeof p.patchedGetPromptCollection === 'function' && p.manager.getPromptCollection === p.patchedGetPromptCollection && typeof p.patchedIsPromptDisabledForActiveCharacter === 'function' && p.manager.isPromptDisabledForActiveCharacter === p.patchedIsPromptDisabledForActiveCharacter);
  }
  function dropGroupGate() {
    const gate = localGate;
    localGate = null;
    if (!gate) return;
    gate.active = false;
    for (const key of Object.keys(gate.original)) {
      if (gate.pm[key] === gate.wrapped[key]) gate.pm[key] = gate.original[key];
    }
  }
  function ensureGroupGate() {
    if (baiBaiActive()) return true;
    const pm = groupManager();
    if (localGate && pm === localGate.pm && Object.keys(localGate.original).every(k => pm[k] === localGate.wrapped[k])) return true;
    dropGroupGate();
    if (!pm) return false;
    const original = { getPromptCollection: pm.getPromptCollection, isPromptDisabledForActiveCharacter: pm.isPromptDisabledForActiveCharacter };
    const gate = { pm, original, wrapped: {}, active: true };
    function book() {
      return pm.serviceSettings?.extensions?.baibaiToolkit?.presetPromptGroups ?? hostCtx()?.chatCompletionSettings?.extensions?.baibaiToolkit?.presetPromptGroups ?? bookOf(readPreset());
    }
    function off(b, id) {
      const gid = b?.prompts?.[id]?.groupId;
      return gid != null && b?.groups?.some(g => g && String(g.id) === String(gid) && g.enabled === false);
    }
    gate.wrapped.isPromptDisabledForActiveCharacter = function(id, ...args) {
      return original.isPromptDisabledForActiveCharacter.call(this, id, ...args) || (gate.active && !!off(book(), id));
    };
    gate.wrapped.getPromptCollection = function(...args) {
      if (!gate.active) return original.getPromptCollection.apply(this, args);
      const b = book();
      if (!b?.groups?.some(g => g?.enabled === false)) return original.getPromptCollection.apply(this, args);
      const entries = this.getPromptOrderForCharacter(this.activeCharacter) || [];
      const ids = new Set(entries.filter(e => e && off(b, e.identifier)).map(e => e.identifier));
      if (!ids.size) return original.getPromptCollection.apply(this, args);
      const restore = [];
      try {
        for (const e of entries) if (e && ids.has(e.identifier) && e.enabled !== false) {
          restore.push([e, Object.prototype.hasOwnProperty.call(e, 'enabled'), e.enabled]);
          e.enabled = false;
        }
        const collection = original.getPromptCollection.apply(this, args);
        if (typeof collection?.add === 'function') {
          const add = collection.add;
          collection.add = function(...prompts) {
            const keep = prompts.filter(p => !ids.has(p?.identifier));
            if (keep.length) return add.apply(this, keep);
          };
        }
        return collection;
      } finally {
        for (const [e, owned, value] of restore) { if (owned) e.enabled = value; else delete e.enabled; }
      }
    };
    localGate = gate;
    try {
      Object.assign(pm, gate.wrapped);
      if (Object.keys(original).every(k => pm[k] === gate.wrapped[k])) return true;
    } catch (e) { /* read-only manager */ }
    dropGroupGate();
    return false;
  }
  function requireGroupGate() {
    if (!ensureGroupGate()) throw new Error('没有可用的生成分组接口；请启用柏宝箱预设分组或更新酒馆助手。未改动条目。');
  }

  async function setCotMode(groupNameTarget) {
    const preset = readPreset();
    const book = bookOf(preset);
    if (!book) throw new Error('这个预设没有柏宝箱分组数据，无法切换思维链模式');
    const cotGroups = book.groups.filter(g => /思维链/.test(String(g.name || '')));
    if (!cotGroups.length) throw new Error('没有找到思维链分组');
    const target = cotGroups.find(g => String(g.name) === String(groupNameTarget));
    if (!target) throw new Error('没有这一组');
    const targetId = String(target.id);
    requireGroupGate();

    await updatePresetWith('in_use', p => {
      const b = bookOf(p);
      if (!b) return p;
      // 分组开关永远照改：装了柏宝箱时组闸门会按它解释（预设里 4 个思维链组本来就是
      // 「分组关、条目开」，别顺手把条目也关了，不然以后在柏宝箱里重新启用会得到一堆关着的条目）。
      const cot = b.groups.filter(g => /思维链/.test(String(g.name || '')));
      cot.forEach(g => { g.enabled = String(g.id) === targetId; });
      return p;
    }, { render: 'debounced' });

    syncBookRuntime(bookOf(readPreset()));
  }

  async function setGroupEnabled(groupId, on) {
    requireGroupGate();
    let payload = null;
    await updatePresetWith('in_use', p => {
      const b = bookOf(p);
      if (!b) return p;
      const g = b.groups.find(x => String(x.id) === String(groupId));
      if (g) g.enabled = !!on;
      payload = bookPayload(b);
      return p;
    }, { render: 'debounced' });
    if (payload) syncBookRuntime(payload);
  }

  async function saveToPreset() {
    const name = presetName();
    if (!name) throw new Error('当前没有命名预设，先在酒馆里另存一份');
    const snap = readPreset();
    await replacePreset(name, snap, { render: 'none' });
    return name;
  }

  /* ---------- 约束联动 ---------- */
  function linkOff(it) {
    const out = [];
    if (!model) return out;
    const isDramaRandom = /^🌟/.test(it.name) && (it.add || []).includes('小剧场');
    const isDrama = (it.add || []).includes('小剧场');
    if (isDrama && model.multiIndex.has('var:小剧场')) {
      const pool = model.multiIndex.get('var:小剧场');
      if (isDramaRandom) pool.forEach(o => { if (o.name !== it.name) out.push(o); });
      else pool.forEach(o => { if (/^🌟/.test(o.name)) out.push(o); });
    }
    const inPlay = it.group === 'NSFW';
    if (inPlay) {
      const random = /^🔥/.test(it.name);
      const isMove = /^⤷/.test(it.name);
      if (random) model.items.forEach(o => { if (o.group === 'NSFW' && /^⤷/.test(o.name)) out.push(o); });
      else if (isMove) model.items.forEach(o => { if (o.group === 'NSFW' && /^🔥/.test(o.name) && o.name !== it.name) out.push(o); });
    }
    return out;
  }

  function requiresOn(it) {
    const out = [];
    if (/^抗截断\s*2$/.test(it.name) && model) {
      const first = model.items.find(x => /^抗截断\s*1$/.test(x.name));
      if (first) out.push(first);
    }
    return out.filter(Boolean);
  }

  /* ---------- 重新读取 ---------- */
  // 监听器只读取，不写回。忽略与面板无关的采样参数变化，避免重画打断操作。
  let displayedState = '';
  function presetState(preset) {
    return JSON.stringify([presetName(), preset && preset.prompts, bookOf(preset)]);
  }
  function refresh(preset = readPreset(), state = presetState(preset)) {
    displayedState = state;
    if (!preset) { model = null; return null; }
    try {
      model = buildModel(preset);
    } catch (err) {
      console.error('[YU球] 读取预设失败', err);
      model = null;
    }
    return model;
  }

  /* ---------- 渲染 ---------- */
  let shadow = null;
  let host = null;
  let panel = null;
  let panelOpen = false;
  let refreshTimer = 0;

