  .ic {
    width: 27px; height: 27px; display: flex; align-items: center; justify-content: center;
    border-radius: 50%; border: 1.5px dashed rgba(139,117,94,.5);
    background: rgba(255,255,255,.6); padding: 0; font-size: 13px; color: #6b5b4a;
    transition: all .18s ease;
  }
  .ic:hover { background: #fff; border-style: solid; border-color: #c89b6f; transform: rotate(-8deg) scale(1.1); }

  /* ===================== 页签：便签标签纸 ===================== */
  /* 页签自动换行：窄屏也全部可见、全部可点，不靠横向滚动 */
  .tabs { display: flex; flex-wrap: wrap; gap: 5px; padding: 8px 12px 7px;
    border-bottom: 1px dashed rgba(139,117,94,.3); }
  .tab {
    flex: 0 0 auto; padding: 4px 11px; border-radius: 2px; font-size: 12px;
    border: 1px solid rgba(139,117,94,.3); background: rgba(255,255,255,.55); color: #6b5b4a;
    opacity: .8; box-shadow: 1.5px 1.5px 0 rgba(139,117,94,.12); transition: all .15s ease;
  }
  .tab:nth-child(odd) { transform: rotate(-.7deg); }
  .tab:nth-child(even) { transform: rotate(.7deg); }
  .tab:hover { opacity: 1; background: #fff; }
  .tab.on { background: #f2e2bd; border-color: #c89b6f; color: #5a4a3a; opacity: 1; font-weight: 600;
    box-shadow: 2px 2px 0 rgba(139,117,94,.2); transform: none; }

  /* ===================== 分组跳转胶囊 ===================== */
  .chips { display: flex; gap: 6px; padding: 7px 12px 3px; overflow-x: auto; scrollbar-width: none; }
  .chips::-webkit-scrollbar { display: none; }
  /* 五选一的跳转入口不能藏在横向滚动区；按面板实际宽度自然换行。 */
  .chips:is([data-nav="cot"], [data-nav="nsfw"]) { flex: none; flex-wrap: wrap; overflow: visible; }
  .chips:is([data-nav="cot"], [data-nav="nsfw"]) .chip { max-width: 100%; min-height: 28px; white-space: normal; overflow-wrap: anywhere; }
  .chips[hidden] { display: none; }
  .chip { flex: 0 0 auto; padding: 2px 9px; border-radius: 999px; font-size: 11px;
    background: rgba(255,255,255,.6); border: 1px dashed rgba(139,117,94,.42); color: #6b5b4a;
    box-shadow: 1.5px 1.5px 0 rgba(139,117,94,.1); transition: all .15s ease; }
  .chip:hover { border-color: #c89b6f; border-style: solid; background: #fff; }
  .chip.on { background: #ecd9b2; border-style: solid; border-color: #c89b6f; font-weight: 600; color: #5a4a3a; }

  /* ===================== 内容区 ===================== */
  .body { flex: 1; overflow-y: auto; overscroll-behavior: contain; padding: 10px 12px 22px; }
  .body::-webkit-scrollbar { width: 8px; }
  .body::-webkit-scrollbar-thumb { background: rgba(139,117,94,.28); border-radius: 4px; }
  .body::-webkit-scrollbar-thumb:hover { background: rgba(139,117,94,.5); }

  /* 分组卡片 */
  .grp { margin: 2px 0 12px; border-radius: 4px; border: 1px solid rgba(139,117,94,.22);
    background: rgba(255,255,255,.4); box-shadow: 2.5px 2.5px 0 rgba(139,117,94,.08); }
  .grp.is-paused { background: rgba(139,117,94,.05); }
  .grp.is-paused .grp-body { opacity: .7; }
  .grp-h { display: flex; align-items: center; gap: 7px; position: sticky; top: -10px; z-index: 2;
    padding: 9px 10px 7px; border-radius: 3px;
    background: linear-gradient(180deg, #f7f2e6 76%, rgba(247,242,230,0));
    font-size: 12.5px; color: #8b6f47; cursor: pointer; user-select: none; }
  .grp-h .chev { flex: 0 0 auto; width: 11px; font-size: 9px; color: #b98f5f; opacity: .8; transition: transform .15s; }
  .grp-h.open .chev { transform: rotate(90deg); }
  .grp-h .gname { font-family: 'STKaiti', 'KaiTi', serif; font-weight: 700; letter-spacing: 1px;
    max-width: 42%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #6b5232; }
  .grp-h .n { flex: 0 0 auto; min-width: 20px; text-align: center; padding: 1px 7px; border-radius: 999px;
    background: rgba(139,117,94,.13); font-size: 10.5px; color: #8b755e; }
  .grp-h .n:empty { display: none; }
  .grp-h .sp { flex: 1; }
  .grp-h.paused .gname { color: #a2987f; }
  .grp-body { display: none; padding: 2px 10px 10px; }
  .grp-body.open { display: block; }
  .mini { flex: 0 0 auto; padding: 2px 8px; font-size: 11px; border-radius: 2px;
    border: 1px dashed rgba(139,117,94,.45); background: rgba(255,255,255,.55); color: #6b5b4a; transition: all .15s; }
  .mini:hover { border-style: solid; border-color: #c89b6f; background: #fff; }
  .gsw { flex: 0 0 auto; width: 36px; height: 20px; border-radius: 999px; border: 1px solid rgba(139,117,94,.38);
    background: rgba(139,117,94,.14); position: relative; padding: 0;
    transition: background .18s, border-color .18s; }
  .gsw::after { content: ''; position: absolute; top: 1.5px; left: 2px; width: 14px; height: 14px; border-radius: 50%;
    background: #fbf6ea; border: 1px solid rgba(139,117,94,.35); box-shadow: 1px 1px 2px rgba(90,74,58,.28);
    transition: left .16s; }
  .gsw[data-on="1"] { background: #d4a574; border-color: #b98f5f; }
  .gsw[data-on="1"]::after { left: 18px; background: #fffef8; }
  .warnbar { margin: 2px 0 8px; padding: 7px 10px; border-radius: 2px; font-size: 11.5px;
    background: rgba(255,235,170,.55); border: 1px dashed rgba(196,120,60,.5); color: #a35a28; }

  /* 条目行 */
  .row { display: flex; align-items: center; gap: 8px; padding: 5px 6px; border-radius: 3px; min-height: 30px;
    transition: background .12s; }
  .row:hover { background: rgba(255,222,140,.35); }
  .row .nm { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #5a4a3a; }
  .row.sub .nm { padding-left: 13px; opacity: .88; }
  .row .tag { flex: 0 0 auto; font-size: 10.5px; color: #8b755e; padding: 1px 5px;
    border: 1px dashed rgba(139,117,94,.42); border-radius: 2px; background: rgba(255,255,255,.5); }
  .row.lock .nm::before { content: '🔒 '; font-size: 11px; }
  .row.lock .nm, .row.ph .nm { opacity: .45; }
  .row.lock:hover .nm, .row.ph:hover .nm { opacity: .8; }
  .sw {
    flex: 0 0 auto; width: 40px; height: 22px; border-radius: 999px; border: 1px solid rgba(139,117,94,.38);
    background: rgba(139,117,94,.14); position: relative; padding: 0;
    transition: background .18s, border-color .18s;
  }
  .sw::after { content: ''; position: absolute; top: 1.5px; left: 2px; width: 16px; height: 16px; border-radius: 50%;
    background: #fbf6ea; border: 1px solid rgba(139,117,94,.35); box-shadow: 1px 1px 2px rgba(90,74,58,.28);
    transition: left .16s; }
  .sw[data-on="1"] { background: #d4a574; border-color: #b98f5f; }
  .sw[data-on="1"]::after { left: 20px; background: #fffef8; }
  .sw[disabled] { opacity: .4; cursor: not-allowed; }

  /* 结构分隔线（手绘虚点线） */
  .struct { display: flex; align-items: center; gap: 8px; margin: 12px 0 4px; font-size: 11.5px;
    color: #8b6f47; letter-spacing: 1.5px; }
  .struct::before, .struct::after { content: ''; flex: 1; border-top: 2px dotted rgba(139,117,94,.35); }
  .struct.end { margin: 4px 0 10px; }

  /* 作者留言 */
  .note { font-size: 11.5px; color: #8a7b63; font-style: italic; padding: 4px 10px; margin: 4px 2px 8px;
    border-left: 3px double rgba(139,117,94,.4); background: rgba(255,255,255,.4); border-radius: 0 3px 3px 0; }

  /* 单选便签 */
  .radio { margin: 6px 2px 10px; padding: 9px 10px; border-radius: 3px; position: relative;
    transform: rotate(-.15deg);
    background: linear-gradient(145deg, #fffdf3 0%, #fbf3dd 100%);
    border: 1px solid rgba(139,117,94,.3); box-shadow: 2px 2px 0 rgba(139,117,94,.1); }
  .radio-h { font-size: 11px; color: #8b6f47; margin-bottom: 7px; display: flex; gap: 6px; align-items: center;
    font-weight: 600; letter-spacing: .5px; }
  .radio-h .k { opacity: .5; font-size: 10px; }
  .opts { display: flex; flex-wrap: wrap; gap: 6px; }
  .opt { padding: 3px 10px; border-radius: 999px; font-size: 12px; color: #6b5b4a;
    border: 1px solid rgba(139,117,94,.35); background: rgba(255,255,255,.7); opacity: .85;
    transition: all .15s; }
  .opt:hover { opacity: 1; border-color: #c89b6f; background: #fff; }
  .opt.on { background: #e8d2a6; border-color: #b98f5f; color: #4f3f2c; opacity: 1; font-weight: 600;
    box-shadow: 1.5px 1.5px 0 rgba(139,117,94,.18); }
  .opt[disabled] { opacity: .4; cursor: not-allowed; }
  .multi-badge { font-size: 10px; color: #5a8a5a; border: 1px dashed rgba(120,170,120,.55); border-radius: 2px;
    padding: 1px 5px; margin-left: 5px; background: rgba(143,188,143,.12); }
  .empty { text-align: center; opacity: .5; padding: 28px 0; color: #8b755e; font-style: italic; }

  /* ===================== 底栏：方案收纳袋 ===================== */
  .ft { display: flex; gap: 6px; padding: 9px 12px; border-top: 1px dashed rgba(139,117,94,.4);
    align-items: center; background: rgba(255,255,255,.35); border-radius: 0 0 13px 13px; }
  .ft select { flex: 1; min-width: 0; background: rgba(255,255,255,.75); color: #5a4a3a;
    border: 1px solid rgba(139,117,94,.35); border-radius: 3px; padding: 5px 7px; font: inherit; outline: none; }
  .ft select:focus { border-color: #d4a574; }
  .ft button { padding: 5px 10px; border-radius: 3px; border: 1px dashed rgba(139,117,94,.45);
    background: rgba(255,255,255,.6); color: #6b5b4a; font-size: 12px; transition: all .15s; }
  .ft button:hover { border-style: solid; border-color: #c89b6f; background: #fff; }

  /* 提示便签 */
  .toast { position: absolute; pointer-events: auto; left: 50%; bottom: 42px;
    transform: translateX(-50%) rotate(-.6deg);
    background: #fffdf4; color: #5a4a3a; border: 1px solid rgba(139,117,94,.45); border-left: 4px solid #d4a574;
    box-shadow: 0 6px 18px rgba(90,74,58,.3);
    padding: 8px 14px; border-radius: 2px; font: 12px/1.4 system-ui, "Microsoft YaHei", sans-serif;
    z-index: 2147483002; max-width: 80vw; text-align: center; }

  .tab:focus-visible, .opt:focus-visible, .ic:focus-visible, .mini:focus-visible, .ft button:focus-visible {
    outline: 2px dashed #c89b6f; outline-offset: 1px;
  }

  /* ===================== 手机端：更大的点击区、铺满、避开安全区 ===================== */
  @media (max-width: 640px) {
    /* 几何用 !important 定死，免得被行内位置或基础 .panel 规则抢回去 */
    .panel {
      left: 8px !important; right: 8px !important; top: 8px !important; bottom: auto !important;
      width: auto !important;
      height: calc(100vh - 16px - env(safe-area-inset-bottom, 0px)) !important;
      height: calc(100dvh - 16px - env(safe-area-inset-bottom, 0px)) !important;
      border-radius: 12px !important;
    }
    .panel { font-size: 13.5px; }
    .hd { padding: 12px 10px 10px; gap: 8px; cursor: default; }
    .hd small { display: none; }
    .tabs { padding: 9px 10px 8px; }
    .tab { padding: 6px 13px; font-size: 12.5px; }
    .tab:nth-child(odd), .tab:nth-child(even) { transform: none; }
    .chip { padding: 4px 10px; font-size: 12px; }
    .body { padding: 10px 10px 24px; }
    .grp-h { padding: 11px 8px 9px; }
    .grp-body { padding: 2px 8px 12px; }
    .row { padding: 8px 6px; min-height: 42px; }
    .sw { width: 46px; height: 26px; }
    .sw::after { width: 18px; height: 18px; }
    .sw[data-on="1"]::after { left: 24px; }
    .gsw { width: 40px; height: 24px; }
    .gsw::after { width: 16px; height: 16px; }
    .gsw[data-on="1"]::after { left: 20px; }
    .opt { padding: 6px 12px; font-size: 12.5px; }
    .mini { padding: 4px 9px; font-size: 11.5px; }
    .ft { padding: 10px 10px calc(10px + env(safe-area-inset-bottom, 0px)); flex-wrap: wrap;
      border-radius: 0 0 11px 11px; }
    .ft select { flex: 1 1 100%; }
    .ft button { padding: 7px 11px; }
    .ball { width: 54px; height: 54px; font-size: 23px; }
  }
  `;

  function toast(text, ms = 2200) {
    if (!shadow) return;
    const old = shadow.querySelector('.toast');
    if (old) old.remove();
    const node = rootDoc.createElement('div');
    node.className = 'toast';
    node.textContent = text;
    shadow.appendChild(node);
    setTimeout(() => node.remove(), ms);
  }

  function currentTab() {
    return TABS.find(t => t.id === ui.tab) || TABS[0];
  }

  const ui = { tab: 'basic', query: '', scroll: {}, open: {} };

  function tabItems(tab) {
    if (!model) return [];
    const all = model.items.filter(it => it.kind === 'toggle' || it.kind === 'stitch' || it.kind === 'note' || it.kind === 'struct' || it.kind === 'locked' || it.kind === 'placeholder');
    if (!tab.groups.length) {
      const used = new Set();
      TABS.forEach(t => t.groups.forEach(k => {
        model.groups.forEach(g => { if (String(g.name).indexOf(k) === 0) used.add(String(g.id)); });
      }));
      return all.filter(it => !it.groupId || !used.has(it.groupId));
    }
    const ids = new Set();
    const orderOf = new Map();
    model.groups.forEach((g, i) => {
      if (tab.groups.some(k => String(g.name).indexOf(k) === 0)) {
        ids.add(String(g.id));
        orderOf.set(String(g.id), Number.isFinite(Number(g.order)) ? Number(g.order) : i);
      }
    });
    return all
      .filter(it => ids.has(String(it.groupId)))
      .sort((a, b) => {
        const ga = orderOf.get(String(a.groupId));
        const gb = orderOf.get(String(b.groupId));
        if (ga !== gb) return (ga == null ? 999 : ga) - (gb == null ? 999 : gb);
        return a.index - b.index;
      });
  }

  function groupTitleOf(it) {
    return it.group || '未分组';
  }

  function itemVisible(it) {
    if (it.kind === 'note' && !store.notes) return false;
    if (it.kind === 'stitch' && !store.stitch) return false;
    return true;
  }

  const CLEAN_LABEL = n => String(n)
    .replace(/^[╭╰┌└]\s*/, '')
    .replace(/\s*[╮╯┐┘]$/, '')
    .replace(/^🔹|^🔸|^🌐|^👥|^🪄|^❤️|^🩷/, '')
    .replace(/^(二选一|三选一|四选一|五选一|单选默认|单选道歉截断可换|选开)｜/, '')
    .trim();

  function itemRowHtml(it, paused) {
    const cls = ['row'];
    if (it.kind === 'locked') cls.push('lock');
    if (it.kind === 'placeholder') cls.push('ph');
    if (it.kind === 'paused') cls.push('ph');
    if (/^⤷/.test(it.name)) cls.push('sub');
    const dead = it.kind === 'locked' || it.kind === 'placeholder' || it.kind === 'struct' || paused;
    let badge = it.kind === 'placeholder' ? '<span class="tag">占位</span>'
      : it.kind === 'locked' ? '<span class="tag">必开</span>' : '';
    if (!badge && /必开/.test(it.name)) badge = '<span class="tag">建议必开</span>';
    if (!badge && it.multi) badge = `<span class="multi-badge">${esc(multiTitle(it.multi))}可叠</span>`;
    if (!badge && paused) badge = '<span class="tag">分组暂停</span>';
    // 暂停的是整组，不是假装组内所有条目都被关掉。
    const on = it.on;
    const dis = dead ? ' disabled' : '';
    return `<div class="${cls.join(' ')}" data-row="${esc(it.key)}">
      <span class="nm" title="${esc(it.name)}">${esc(it.name)}${badge}</span>
      <button class="sw" data-sw="${esc(it.key)}" data-on="${on ? '1' : '0'}"${dis}></button>
    </div>`;
  }

  function radioHtml(key, list, paused) {
    const current = list.filter(it => it.on);
    const opts = list.map(it => `<button class="opt${it.on ? ' on' : ''}" data-opt="${esc(key)}" data-name="${esc(it.key)}"${paused ? ' disabled' : ''}>${esc(CLEAN_LABEL(it.name))}</button>`).join('');
    const badge = current.length > 1 ? '<span class="tag" style="color:#b0662f;border-color:rgba(176,102,47,.5);background:rgba(255,205,130,.4)">多开</span>' : '';
    return `<div class="radio" data-radio="${esc(key)}">
      <div class="radio-h">只能选一个 · ${esc(radioTitle(key))}${badge}</div>
      <div class="opts">${opts}</div>
    </div>`;
  }

  function groupOpenState(name) {
    return ui.open[ui.tab + '|' + name] === true;
  }

  /** 手风琴：同一页只展开一组，页面才不会越滚越长。 */
  function setGroupOpen(name, open) {
    if (open) {
      const prefix = ui.tab + '|';
      Object.keys(ui.open).forEach(k => { if (k.indexOf(prefix) === 0) ui.open[k] = false; });
    }
    ui.open[ui.tab + '|' + name] = !!open;
  }

  function groupNamesOf(items) {
    const names = [];
    items.forEach(it => {
      const n = groupTitleOf(it);
      if (!names.includes(n)) names.push(n);
    });
    return names;
  }

  function ensureDefaultOpen(items) {
    const prefix = ui.tab + '|';
    const hasAny = Object.keys(ui.open).some(k => k.indexOf(prefix) === 0);
    if (hasAny) return;
    const names = groupNamesOf(items);
    if (names.length) ui.open[prefix + names[0]] = true;
  }

  function buildBodyHtml(items, q) {
    const out = [];
    let currentGroup = null;
    const renderedRadio = new Set();

    const openGroup = name => {
      if (currentGroup === name) return;
      if (currentGroup !== null) out.push('</div></section>');
      currentGroup = name;
      const g = model.groups.find(x => String(x.name) === name);
      const total = items.filter(i => groupTitleOf(i) === name).length;
      const disabled = !!(g && g.enabled === false);
      const open = q ? true : groupOpenState(name);
      out.push(`<section class="grp${disabled ? ' is-paused' : ''}" data-grp="${esc(name)}">
        <div class="grp-h${open ? ' open' : ''}${disabled ? ' paused' : ''}" data-grp-head="${esc(name)}">
          <span class="chev">▶</span>
          <span class="gname">${esc(name)}</span>
          <span class="n">${q ? '' : total}</span>
          <span class="sp"></span>
          ${q ? '' : `<button class="mini" data-grp-all="${esc(name)}" data-next="1">全开</button><button class="mini" data-grp-all="${esc(name)}" data-next="0">全关</button>`}
          ${g ? `<button class="gsw" data-grp-sw="${esc(g.id)}" data-on="${disabled ? '0' : '1'}" title="暂停 / 恢复整组（保留条目开关）"></button>` : ''}
        </div>
        <div class="grp-body${open ? ' open' : ''}">
        ${disabled ? `<div class="warnbar">${ensureGroupGate() ? '分组已暂停：生成时跳过本组；恢复后按各条目当前开关生效。' : '本组标记为暂停，但当前没有可用的生成分组接口，无法保证跳过。'}</div>` : ''}`);
    };

    items.forEach(it => {
      if (!itemVisible(it)) return;
      openGroup(groupTitleOf(it));
      const paused = (() => {
        const g = model.groups.find(x => String(x.id) === String(it.groupId));
        return !!g && g.enabled === false;
      })();
      if (it.kind === 'struct') {
        if (/^[╰└]/.test(it.name)) { out.push('<div class="struct end"></div>'); return; }
        out.push(`<div class="struct" data-section="${esc(it.key)}">${esc(CLEAN_LABEL(it.name) || '分组')}</div>`);
        return;
      }
      if (it.kind === 'note') {
        out.push(`<div class="note">${esc(it.name.replace(/^🐟💬\s*/, ''))}</div>`);
        return;
      }
      if (it.radio) {
        if (renderedRadio.has(it.radio)) return;
        renderedRadio.add(it.radio);
        const list = model.radioIndex.get(it.radio) || [];
        const visible = list.filter(x => itemVisible(x) && groupTitleOf(x) === groupTitleOf(it));
        if (visible.length >= 2) { out.push(radioHtml(it.radio, visible, paused)); return; }
      }
      out.push(itemRowHtml(it, paused));
    });

    if (currentGroup !== null) out.push('</div></section>');
    return out.join('');
  }

  function renderBody() {
    if (!shadow) return;
    const body = shadow.querySelector('.body');
    if (!body) return;
    if (!model) {
      body.innerHTML = '<div class="empty">读不到当前预设。确认酒馆里已经加载预设。</div>';
      return;
    }
    const top = (ui.scroll && ui.scroll[ui.tab]) || 0;
    const q = ui.query.trim().toLowerCase();
    const tab = currentTab();
    let items = tabItems(tab);
    if (q) items = model.items.filter(it => it.name.toLowerCase().indexOf(q) >= 0);
    else ensureDefaultOpen(items);
    const html = buildBodyHtml(items, q);
    body.innerHTML = html || '<div class="empty">这一页没有条目。</div>';
    body.scrollTop = top;
    renderChips();
  }

  function renderChips() {
    if (!shadow) return;
    const bar = shadow.querySelector('.chips');
    if (!bar) return;
    if (!model || ui.query.trim()) { bar.hidden = true; bar.innerHTML = ''; return; }
    const items = tabItems(currentTab());
    const names = groupNamesOf(items);
    const sections = ui.tab === 'nsfw' ? items.filter(it => itemVisible(it) && it.kind === 'struct' && !/^[╰└]/.test(it.name)) : [];
    if (names.length < 2 && !sections.length) { bar.hidden = true; bar.innerHTML = ''; return; }
    bar.hidden = false;
    bar.dataset.nav = ui.tab;
    bar.innerHTML = names.map(n => {
      // 只简化这五个已知组的显示文字，跳转仍使用预设中的完整组名。
      const label = ui.tab === 'cot' && currentTab().groups.includes(n)
        ? n.replace(/^五选一｜/, '').replace(/思维链$/, '') : n;
      return `<button class="chip${groupOpenState(n) ? ' on' : ''}" data-chip="${esc(n)}" title="${esc(n)}" aria-label="跳转到${esc(n)}">${esc(label)}</button>`;
    }).join('') + sections.map(it => {
      const label = CLEAN_LABEL(it.name) || '分段';
      return `<button class="chip" data-jump-section="${esc(it.key)}" title="${esc(it.name)}">${esc(label)}</button>`;
    }).join('');
  }

  function jumpToGroup(name) {
    setGroupOpen(name, true);
    renderBody();
    const sec = [...shadow.querySelectorAll('.grp')].find(s => s.dataset.grp === name);
    if (sec) sec.scrollIntoView({ block: 'start', behavior: 'smooth' });
  }

  function renderTabs() {
    if (!shadow) return;
    const nav = shadow.querySelector('.tabs');
    if (!nav) return;
    nav.innerHTML = TABS.map(t => `<button class="tab${t.id === ui.tab ? ' on' : ''}" data-tab="${t.id}">${t.title}</button>`).join('');
  }

  function renderCotBanner() {
    if (!shadow || !model) return;
    const bar = shadow.querySelector('[data-cot]');
    if (!bar) return;
    if (ui.tab !== 'cot') { bar.hidden = true; bar.innerHTML = ''; return; }
    const cot = model.groups.filter(g => /思维链/.test(String(g.name || '')));
    const onG = cot.filter(g => g.enabled !== false);
    const currentTxt = onG.length > 1
      ? onG.map(g => String(g.name).replace(/^五选一｜/, '')).join('、') + '（多组同时生效，点一下想要的模式即可收敛为单选）'
      : (onG.length ? esc(onG.map(g => String(g.name).replace(/^五选一｜/, '')).join('、')) : '全部关闭');
    const hint = '';
    bar.hidden = false;
    bar.innerHTML = `<div class="warnbar" style="background:rgba(212,165,116,.16);border-color:rgba(185,143,95,.55);color:#8b6f47">
      <b>思维链五选一</b>　当前：${currentTxt}${hint}
      <div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:6px">
      ${cot.map(g => `<button class="opt${g.enabled !== false ? ' on' : ''}" data-cot-mode="${esc(String(g.name))}">${esc(String(g.name).replace(/^五选一｜/, ''))}</button>`).join('')}
      </div></div>`;
  }

  function renderAll() {
    renderTabs();
    renderCotBanner();
    renderBody();
    renderChips();
  }

  /* ---------- 交互 ---------- */
  function itemByKey(key) {
    return model ? model.byKey.get(String(key)) : null;
  }

  async function toggleItem(key) {
    const it = itemByKey(key);
    if (!it) return;
    if (it.kind === 'locked' || it.kind === 'placeholder' || it.kind === 'struct') {
      toast(it.kind === 'locked' ? '这条是必开项（清零），不能关' : '这条是结构行，不在这里改');
      return;
    }
    const next = !it.on;
    const plan = new Map([[it.key, next]]);

    if (next && it.radio) {
      (model.radioIndex.get(it.radio) || []).forEach(o => { if (o.key !== it.key && o.on) plan.set(o.key, false); });
    }
    if (next) linkOff(it).forEach(o => plan.set(o.key, false));
    if (next) requiresOn(it).forEach(o => plan.set(o.key, true));

    const pairs = [...plan].map(([k, on]) => ({ key: k, on }));
    applying = true;
    try {
      await enqueue(() => commitEnabled(pairs));
      refresh();
      renderBody();
      const g = it.groupId ? model.groups.find(x => String(x.id) === String(it.groupId)) : null;
      if (g && g.enabled === false) toast(`「${it.name}」已改，但它所在分组「${g.name}」处于暂停状态`);
      else if (plan.size > 1) toast(`同时调整了 ${plan.size - 1} 条`);
    } catch (err) {
      console.error('[YU球] 改开关失败', err);
      toast('没改成，看控制台');
    } finally {
      applying = false;
    }
  }

  async function setRadio(key, itemKey) {
    const list = model && model.radioIndex.get(key);
    if (!list) return;
    applying = true;
    try {
      const pairs = list.map(o => ({ key: o.key, on: o.key === itemKey }));
      await enqueue(() => commitEnabled(pairs));
      refresh();
      renderBody();
    } catch (err) {
      console.error('[YU球] 单选失败', err);
      toast('没改成，看控制台');
    } finally {
      applying = false;
    }
  }

  async function groupAll(groupName, on) {
    /* 开头先重建 model：判断「要不要解除暂停」必须用最新预设，
       别拿可能过期的缓存（分组开关、柏宝箱都可能刚改过预设）。 */
    refresh();
    if (!model) return;
    const g = model.groups.find(x => String(x.name) === groupName);
    const list = model.items.filter(it => groupTitleOf(it) === groupName && (it.kind === 'toggle' || it.kind === 'stitch') && it.name !== RESET_NAME);
    if (!list.length && !g) return;
    applying = true;
    try {
      if (list.length) await enqueue(() => commitEnabled(list.map(it => ({ key: it.key, on }))));
      /* 关键：组处于「暂停」时点全开，必须顺手解除暂停，否则条目写了也不显示、不生效
         （YU 的思维链组出厂就是暂停态，正是在这种组里点全开会看起来毫无反应）。 */
      if (on && g && g.enabled === false) {
        await enqueue(() => setGroupEnabled(g.id, true, { noCascade: true }));
      }
      refresh();
      renderBody();
      toast(on ? `「${groupName}」全开` : `「${groupName}」全关`);
    } catch (err) {
      console.error(err);
      toast('没改成，看控制台');
    } finally {
      applying = false;
    }
  }

  /* ---------- 面板骨架 ---------- */
  function ensurePanel() {
    if (panel) return panel;
    panel = rootDoc.createElement('div');
    panel.className = 'panel';
    panel.hidden = true;
    panel.innerHTML = `
      <div class="hd" data-drag>
        <b>YU</b><small>${VERSION}</small>
        <span class="sp"></span>
        <input class="search" data-search placeholder="搜条目">
        <button class="ic" data-act="edit-entry" aria-label="查看或编辑条目正文" title="查看或编辑条目正文">✎</button>
        <button class="ic" data-act="big" title="放大 / 还原">⤢</button>
        <button class="ic" data-act="save" title="保存到预设">💾</button>
        <button class="ic" data-act="close" title="收起">×</button>
      </div>
      <div class="tabs"></div>
      <div class="chips" data-chips hidden></div>
      <div data-cot hidden style="padding:8px 10px 0"></div>
      <div class="body"></div>`;
    host.shadowRoot.appendChild(panel);
    const body = panel.querySelector('.body');
    if (body) body.addEventListener('scroll', () => { ui.scroll[ui.tab] = body.scrollTop; });
    bindPanelDrag();
    return panel;
  }

  /* ---------- 面板位置：电脑可拖 + 手机铺满 ---------- */
  const PANEL_POS_KEY = 'yu-ball-panel-pos';

  function isNarrow() {
    try {
      if (typeof rootWin.matchMedia === 'function') return rootWin.matchMedia('(max-width: 640px)').matches;
    } catch (e) { /* ignore */ }
    return rootWin.innerWidth <= 640;
  }

  function loadPanelPos() {
    try { return JSON.parse(rootWin.localStorage.getItem(PANEL_POS_KEY) || 'null'); } catch (e) { return null; }
  }

  function savePanelPos(left, top) {
    try { rootWin.localStorage.setItem(PANEL_POS_KEY, JSON.stringify({ left, top })); } catch (e) { /* ignore */ }
  }

  function layoutPanel() {
    if (!panel) return;
    if (isNarrow()) {
      // 手机几何由 CSS 媒体查询（!important）接管，这里只清掉桌面留下的行内位置
      panel.classList.add('narrow');
      panel.style.left = '';
      panel.style.right = '';
      panel.style.top = '';
      panel.style.bottom = '';
      panel.style.width = '';
      panel.style.height = '';
      return;
    }
    panel.classList.remove('narrow');
    panel.style.width = '';
    panel.style.height = '';
    const pos = loadPanelPos();
    if (!pos || !Number.isFinite(pos.left) || !Number.isFinite(pos.top)) {
      // 没拖过就用 CSS 的默认位置（左下、球上方），别抢用户习惯
      panel.style.left = '';
      panel.style.top = '';
      panel.style.right = '';
      panel.style.bottom = '';
      return;
    }
    const w = panel.offsetWidth || 430;
    const h = panel.offsetHeight || 520;
    const left = clamp(pos.left, 4, Math.max(4, rootWin.innerWidth - w - 4));
    const top = clamp(pos.top, 4, Math.max(4, rootWin.innerHeight - h - 4));
    panel.style.left = Math.round(left) + 'px';
    panel.style.top = Math.round(top) + 'px';
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
  }

  function bindPanelDrag() {
    const handle = panel.querySelector('[data-drag]');
    if (!handle) return;
    let dragging = false;
    let sx = 0;
    let sy = 0;
    let ox = 0;
    let oy = 0;
    let pid = null;

    handle.addEventListener('pointerdown', e => {
      if (isNarrow()) return;
      if (e.target.closest('input, button')) return;
      const rect = panel.getBoundingClientRect();
      dragging = true;
      pid = e.pointerId;
      sx = e.clientX; sy = e.clientY;
      ox = rect.left; oy = rect.top;
      try { handle.setPointerCapture(pid); } catch (err) { /* ignore */ }
      panel.style.right = 'auto';
      panel.style.bottom = 'auto';
      e.preventDefault();
    });
    handle.addEventListener('pointermove', e => {
      if (!dragging || e.pointerId !== pid) return;
      const w = panel.offsetWidth;
      const h = panel.offsetHeight;
      const left = clamp(ox + (e.clientX - sx), 4, Math.max(4, rootWin.innerWidth - w - 4));
      const top = clamp(oy + (e.clientY - sy), 4, Math.max(4, rootWin.innerHeight - h - 4));
      panel.style.left = Math.round(left) + 'px';
      panel.style.top = Math.round(top) + 'px';
    });
    const end = e => {
      if (!dragging || (e && e.pointerId !== pid)) return;
      dragging = false;
      try { handle.releasePointerCapture(pid); } catch (err) { /* ignore */ }
      const rect = panel.getBoundingClientRect();
      savePanelPos(rect.left, rect.top);
    };
    handle.addEventListener('pointerup', end);
    handle.addEventListener('pointercancel', end);
  }

  function openPanel() {
    ensurePanel();
    panel.hidden = false;
    panelOpen = true;
    if (ui.query === '') {
      const box = shadow.querySelector('[data-search]');
      if (box && box.value) { box.value = ''; }
    }
    refresh();
    renderAll();
    layoutPanel();
  }

  function closePanel() {
    if (!panel) return;
    panel.hidden = true;
    panelOpen = false;
  }

  function togglePanel() {
    if (panelOpen) closePanel(); else openPanel();
  }

  function openEntryEditor() {
    const preset = readPreset();
    const owner = presetName();
    if (!preset) { toast('读不到当前预设'); return; }
    const keyOf = p => String(p && (p.identifier || p.id) || '');
    const placeholder = p => PLACEHOLDER_IDS.has(p.id) || PLACEHOLDER_IDS.has(p.identifier) ||
      (typeof isPresetPlaceholderPrompt === 'function' && isPresetPlaceholderPrompt(p));
    const entries = [];
    for (const slot of ['prompts', 'prompts_unused']) {
      (preset[slot] || []).forEach(p => { if (p) entries.push({ slot, p }); });
    }
    if (!entries.length) { toast('当前预设没有条目'); return; }
    const dialog = rootDoc.createElement('dialog');
    // Native modal isolates the draft from renderAll / SETTINGS_UPDATED.
    dialog.className = 'panel';
    dialog.style.cssText = 'position:fixed;inset:0;margin:auto;display:block;height:fit-content;padding:1rem;width:min(34rem,92vw);max-height:85vh;overflow:auto';
    dialog.setAttribute('aria-label', '预设条目正文');
    dialog.innerHTML = '<header class="hd" style="cursor:default"><b>查看 / 编辑预设条目</b></header><p><label>条目 <select class="search" style="max-width:100%"></select></label></p><small data-meta></small><p><label>正文<textarea class="search" rows="12" style="width:100%;display:block;resize:vertical"></textarea></label></p><p role="status"></p><footer class="ft"><button type="button" data-write>应用到当前预设</button><button type="button" data-done>关闭</button></footer>';
    const select = dialog.querySelector('select'), text = dialog.querySelector('textarea');
    const write = dialog.querySelector('[data-write]'), done = dialog.querySelector('[data-done]');
    const status = dialog.querySelector('[role=status]');
    let index = 0, base = '', busy = false, writable = false;
    const original = new Map();
    entries.forEach(({ p, slot }, i) => {
      const opt = rootDoc.createElement('option'); opt.value = String(i);
      opt.textContent = (slot === 'prompts_unused' ? '未使用 · ' : '') + (p.name || '未命名') + ' · ' + (keyOf(p) || '#' + (i + 1));
      select.appendChild(opt);
    });
    const dirty = () => writable && text.value !== base;
    const mayLeave = () => !busy && (!dirty() || rootWin.confirm('放弃这条尚未应用的正文修改？'));
    function display(i) {
      index = i;
      const { p, slot } = entries[i];
      const raw = original.has(i) ? original.get(i) : p.content;
      text.value = typeof raw === 'string' ? raw : '';
      base = text.value; // textarea normalizes CRLF; retain raw for conflict detection.
      original.set(i, raw);
      writable = !!owner && !!keyOf(p) && !placeholder(p) && typeof raw === 'string';
      text.readOnly = !writable;
      write.disabled = true;
      dialog.querySelector('[data-meta]').textContent = [owner, slot === 'prompts' ? '已编排' : '未使用', p.role, keyOf(p)].filter(Boolean).join(' · ');
      status.textContent = writable ? '应用后立即生效；需永久保存时再点面板的保存按钮。' : '只读：占位符没有可编辑正文，或缺少安全写入所需的信息。';
    }
    text.addEventListener('input', () => { write.disabled = !dirty(); });
    select.addEventListener('change', () => { if (mayLeave()) display(select.selectedIndex); else select.selectedIndex = index; });
    const close = () => { if (mayLeave()) dialog.close(); };
    done.addEventListener('click', close);
    dialog.addEventListener('cancel', e => { e.preventDefault(); close(); });
    dialog.addEventListener('keydown', e => { e.stopPropagation(); });
    dialog.addEventListener('close', () => dialog.remove(), { once: true });
    write.addEventListener('click', async () => {
      if (busy || !dirty()) return;
      const { slot, p } = entries[index], key = keyOf(p), prev = original.get(index), next = text.value;
      busy = true; write.disabled = done.disabled = select.disabled = true; text.readOnly = true;
      try {
        await enqueue(() => {
          if (presetName() !== owner) throw new Error('预设已切换');
          return updatePresetWith('in_use', current => {
            if (presetName() !== owner) throw new Error('预设已切换');
            const matches = (current[slot] || []).filter(x => x && keyOf(x) === key);
            if (matches.length !== 1) throw new Error('条目已移动、删除或 ID 重复');
            const target = matches[0];
            if (placeholder(target) || target.content !== prev) throw new Error('正文已在外部修改或不再可编辑');
            target.content = next;
            return current;
          }, { render: 'debounced' });
        });
        original.set(index, next); base = next;
        status.textContent = '已应用到当前使用中的预设；未写回命名预设。';
        refresh(); renderAll();
      } catch (err) { status.textContent = '未能应用：' + (err.message || err) + '。草稿仍在，可复制后重新打开。'; }
      finally { busy = false; done.disabled = select.disabled = false; text.readOnly = !writable; write.disabled = !dirty(); }
    });
    display(0); shadow.appendChild(dialog);
    try { dialog.showModal(); } catch (err) { dialog.remove(); toast('当前浏览器无法打开条目编辑器'); }
  }

  function onShadowClick(e) {
    const t = e.target;
    if (!t || !t.closest) return;

    const tab = t.closest('[data-tab]');
    if (tab) {
      ui.tab = tab.getAttribute('data-tab');
      ui.query = '';
      ui.scroll[ui.tab] = 0;
      const s = shadow.querySelector('[data-search]');
      if (s) s.value = '';
      renderAll();
      return;
    }

    const sw = t.closest('[data-sw]');
    if (sw) { toggleItem(sw.getAttribute('data-sw')); return; }

    const opt = t.closest('[data-opt]');
    if (opt) { setRadio(opt.getAttribute('data-opt'), opt.getAttribute('data-name')); return; }

    const cot = t.closest('[data-cot-mode]');
    if (cot) {
      const name = cot.getAttribute('data-cot-mode');
      applying = true;
      enqueue(async () => { await setCotMode(name); })
        .then(() => { refresh(); renderAll(); toast(`思维链切到「${name.replace(/^五选一｜/, '')}」`); })
        .catch(err => { console.error(err); toast('切换失败：' + err.message); })
        .finally(() => { applying = false; });
      return;
    }

    const gt = t.closest('[data-grp-sw]');
    if (gt) {
      const id = gt.getAttribute('data-grp-sw');
      const next = gt.getAttribute('data-on') !== '1';
      gt.setAttribute('data-on', next ? '1' : '0');
      enqueue(() => setGroupEnabled(id, next))
        .then(() => { refresh(); renderAll(); toast(next ? '分组已恢复，保留条目开关' : '分组已暂停，保留条目开关'); })
        .catch(err => { toast('分组没改成：' + err.message); refresh(); renderAll(); });
      return;
    }

    const ga = t.closest('[data-grp-all]');
    if (ga) { groupAll(ga.getAttribute('data-grp-all'), ga.getAttribute('data-next') === '1'); return; }

    const ghead = t.closest('[data-grp-head]');
    if (ghead) {
      const name = ghead.getAttribute('data-grp-head');
      const open = !groupOpenState(name);
      setGroupOpen(name, open);
      shadow.querySelectorAll('.grp').forEach(sec => {
        const n = sec.getAttribute('data-grp') || '';
        const o = ui.query.trim() ? true : groupOpenState(n);
        const b = sec.querySelector('.grp-body');
        const h = sec.querySelector('.grp-h');
        if (b) b.classList.toggle('open', o);
        if (h) h.classList.toggle('open', o);
      });
      renderChips();
      return;
    }

    const sectionChip = t.closest('[data-jump-section]');
    if (sectionChip) {
      const it = itemByKey(sectionChip.dataset.jumpSection);
      if (!it) return;
      const group = groupTitleOf(it);
      if (!groupOpenState(group)) { setGroupOpen(group, true); renderBody(); }
      const target = [...shadow.querySelectorAll('[data-section]')].find(el => el.dataset.section === it.key);
      if (target) target.scrollIntoView({ block: 'start', behavior: 'smooth' });
      return;
    }
    const chip = t.closest('[data-chip]');
    if (chip) { jumpToGroup(chip.getAttribute('data-chip')); return; }

    const act = t.closest('[data-act]');
    if (act) {
      const a = act.getAttribute('data-act');
      if (a === 'close') { closePanel(); return; }
      if (a === 'edit-entry') { openEntryEditor(); return; }
      if (a === 'big') {
        panel.classList.toggle('big');
        layoutPanel();
        return;
      }
      if (a === 'save') {
        enqueue(saveToPreset)
          .then(name => toast(`已写回预设「${name}」`))
          .catch(err => { console.error(err); toast('保存失败：' + err.message); });
        return;
      }

    }
  }

  function onShadowInput(e) {
    const t = e.target;
    if (!t) return;
    if (t.matches && t.matches('[data-search]')) {
      ui.query = String(t.value || '');
      renderBody();
    }
  }

  /* ---------- 悬浮球拖拽 ---------- */
  function loadPos() {
    try { return JSON.parse(rootWin.localStorage.getItem(POS_KEY) || 'null'); } catch (e) { return null; }
  }

  function savePos(x, y) {
    try { rootWin.localStorage.setItem(POS_KEY, JSON.stringify({ x, y })); } catch (e) { /* ignore */ }
  }

  // 首次定位、拖动和恢复使用同一坐标系：实际可视视口 → 固定宿主内坐标。
  function positionBall(ball, pos) {
    if (!ball || !host) return;
    const vv = rootWin.visualViewport;
    const useVV = vv && vv.width > 0 && vv.height > 0;
    const left = useVV ? vv.offsetLeft : 0, top = useVV ? vv.offsetTop : 0;
    const w = useVV ? vv.width : rootWin.innerWidth, h = useVV ? vv.height : rootWin.innerHeight;
    if (!(w > 0 && h > 0)) return;
    const style = rootWin.getComputedStyle(ball);
    const inset = side => parseFloat(style.getPropertyValue('scroll-margin-' + side)) || 0;
    const minX = left + inset('left') + 4, minY = top + inset('top') + 8;
    const maxX = Math.max(minX, left + w - ball.offsetWidth - inset('right') - 4);
    const maxY = Math.max(minY, top + h - ball.offsetHeight - inset('bottom') - 4);
    const valid = pos && Number.isFinite(pos.x) && Number.isFinite(pos.y);
    const x = clamp(valid ? pos.x : minX + 10, minX, maxX);
    const y = clamp(valid ? pos.y : maxY - 92, minY, maxY);
    const origin = host.getBoundingClientRect();
    ball.style.left = Math.round(x - origin.left) + 'px';
    ball.style.top = Math.round(y - origin.top) + 'px';
    ball.style.bottom = 'auto';
    return {x, y};
  }

  function placeBall(ball) { positionBall(ball, loadPos()); }

  function bindDrag(ball) {
    let sx = 0; let sy = 0; let ox = 0; let oy = 0; let moving = false;
    ball.addEventListener('pointerdown', e => {
      moving = false;
      sx = e.clientX; sy = e.clientY;
      const r = ball.getBoundingClientRect();
      ox = r.left; oy = r.top;
      ball.setPointerCapture(e.pointerId);
    });
    ball.addEventListener('pointermove', e => {
      if (!ball.hasPointerCapture(e.pointerId)) return;
      const dx = e.clientX - sx; const dy = e.clientY - sy;
      if (!moving && Math.abs(dx) + Math.abs(dy) < 5) return;
      moving = true;
      positionBall(ball, { x: ox + dx, y: oy + dy });
    });
    ball.addEventListener('pointerup', e => {
      if (!ball.hasPointerCapture(e.pointerId)) return;
      ball.releasePointerCapture(e.pointerId);
      if (moving) { const r = ball.getBoundingClientRect(); savePos(r.left, r.top); }
      else togglePanel();
    });
  }

  function onViewport() {
    if (panelOpen) layoutPanel();
    if (shadow) placeBall(shadow.querySelector('.ball'));
  }

  /* ---------- 启动 ---------- */
  function mount() {
    if (!rootDoc || !rootDoc.body) {
      console.error('[YU球] 找不到可挂载的 document.body');
      return false;
    }
    const old = rootDoc.getElementById(HOST_ID);
    if (old) old.remove();
    host = rootDoc.createElement('div');
    host.id = HOST_ID;
    host.setAttribute('data-yu-ball', VERSION);
    host.style.cssText =
      'position:fixed;left:0;top:0;right:0;bottom:0;width:auto;height:auto;overflow:visible;z-index:2147483000;pointer-events:none;';
    rootDoc.body.appendChild(host);

    if (typeof host.attachShadow !== 'function') {
      console.error('[YU球] 这个环境没有 Shadow DOM，挂不上面板');
      host.remove();
      return false;
    }
    shadow = host.attachShadow({ mode: 'open' });
    const style = rootDoc.createElement('style');
    style.textContent = CSS;
    shadow.appendChild(style);

    const ball = rootDoc.createElement('div');
    ball.className = 'ball';
    ball.textContent = '📝';
    ball.title = 'YU 悬浮球 ' + VERSION;
    shadow.appendChild(ball);
    placeBall(ball);
    bindDrag(ball);

    shadow.addEventListener('click', onShadowClick);
    shadow.addEventListener('input', onShadowInput);
    rootDoc.addEventListener('keydown', onKeyDown);
    rootWin.addEventListener('resize', onViewport);
    rootWin.addEventListener('orientationchange', onViewport);
    const vv = rootWin.visualViewport;
    if (vv) {
      vv.addEventListener('resize', onViewport);
      vv.addEventListener('scroll', onViewport);
      stops.push(() => vv.removeEventListener('scroll', onViewport));
    }
    // 从脚本库也能找回球，不依赖点到原来的悬浮位置。
    try {
      const sub = eventOn(getButtonEvent('YU'), () => {
        const pos = positionBall(ball, null);
        if (pos) savePos(pos.x, pos.y);
      });
      if (sub && typeof sub.stop === 'function') stops.push(() => sub.stop());
      else if (typeof sub === 'function') stops.push(sub);
    } catch (e) { /* 旧版酒馆助手没有脚本按钮事件 */ }
    return true;
  }

  function onKeyDown(e) {
    if (e.key === 'Escape' && panelOpen) closePanel();
  }

  let stops = [];

  /** 酒馆助手每换一次聊天可能重跑脚本，旧的一份要先摘干净，不然监听会叠起来。 */
  function cleanup() {
    dropGroupGate();
    stops.forEach(fn => { try { fn(); } catch (e) { /* ignore */ } });
    stops = [];
    try { rootDoc.removeEventListener('keydown', onKeyDown); } catch (e) { /* ignore */ }
    try { rootWin.removeEventListener('resize', onViewport); } catch (e) { /* ignore */ }
    try { rootWin.removeEventListener('orientationchange', onViewport); } catch (e) { /* ignore */ }
    try {
      if (rootWin.visualViewport) rootWin.visualViewport.removeEventListener('resize', onViewport);
    } catch (e) { /* ignore */ }
    if (host && host.parentNode) host.parentNode.removeChild(host);
    host = null;
    shadow = null;
    panel = null;
    panelOpen = false;
  }

  function watchPreset() {
    function syncIfChanged() {
      if (!panelOpen || applying || rootDoc.hidden) return;
      const preset = readPreset();
      const state = presetState(preset);
      if (state === displayedState) return;
      refresh(preset, state);
      renderAll();
    }
    function scheduleSync() {
      ensureGroupGate();
      if (!panelOpen || refreshTimer) return;
      refreshTimer = setTimeout(() => { refreshTimer = 0; syncIfChanged(); }, 50);
    }
    function subscribe(name, fn) {
      try {
        const type = tavern_events[name];
        if (!type) return;
        const sub = eventOn(type, fn);
        if (typeof sub === 'function') stops.push(sub);
        else if (sub && typeof sub.stop === 'function') stops.push(() => sub.stop());
      } catch (e) { /* 旧版酒馆可能缺少事件 */ }
    }
    ['SETTINGS_UPDATED', 'OAI_PRESET_CHANGED_AFTER', 'PRESET_CHANGED'].forEach(k => subscribe(k, scheduleSync));
    // 原生提示词管理器的眼睛按钮不一定发 SETTINGS_UPDATED；捕获委托也适配列表重建。
    const fromManager = e => {
      if (e.target && e.target.closest && e.target.closest('#completion_prompt_manager, #completion_prompt_manager_list')) scheduleSync();
    };
    ['click', 'change'].forEach(type => {
      rootDoc.addEventListener(type, fromManager, true);
      stops.push(() => rootDoc.removeEventListener(type, fromManager, true));
    });
    // 柏宝箱或其他脚本也能静默更新预设；仅在面板可见时兜底读取。
    const poll = setInterval(syncIfChanged, 900);
    stops.push(() => { clearInterval(poll); clearTimeout(refreshTimer); refreshTimer = 0; });
    subscribe('CHAT_CHANGED', () => {
        if (panelOpen) {
          refresh();
          renderAll();
        }
    });
    window.addEventListener('pagehide', cleanup);
    stops.push(() => window.removeEventListener('pagehide', cleanup));
  }

  function boot() {
    try {
      if (typeof rootWin.__yuBallCleanup === 'function') rootWin.__yuBallCleanup();
    } catch (e) { /* ignore */ }
    store = readGlobalStore();
    if (!mount()) return;
    rootWin.__yuBallCleanup = cleanup;
    ensureGroupGate();
    watchPreset();
  }

  /* 导出纯函数，方便在酒馆控制台调试，也方便离线测 */
  try {
    const api = {
      VERSION, TABS, buildModel, readVars, kindOf, radioTitle, multiTitle,
      baiBaiActive, _ensureGroupGate: ensureGroupGate, _dropGroupGate: dropGroupGate, _setGroupEnabled: setGroupEnabled, _setCotMode: setCotMode, _groupAll: groupAll,
      _toggleItem: toggleItem,
      _setModel(m) { model = m; store = store || {}; },
      _setStore(s) { store = Object.assign({}, store, s); },
      _tabs() { return TABS.map(t => { ui.tab = t.id; return { id: t.id, title: t.title, items: tabItems(t) }; }); },
      _bodyHtml(items, q) { ui.query = q || ''; return buildBodyHtml(items, q || ''); },
      _css() { return CSS; },
      _mount() { return mount(); },
      _open() { openPanel(); },
      _close() { closePanel(); },
      _host: () => host,
      _rootDoc: () => rootDoc,
    };
    if (typeof window !== 'undefined') window.__YU_BALL__ = api;
  } catch (e) { /* ignore */ }

  let bootTries = 0;
  function start() {
    bootTries += 1;
    if (!rootDoc || !rootDoc.body) {
      if (bootTries < 100) { setTimeout(start, 300); return; }
      console.error('[YU球] 等不到页面 body，脚本无法挂载');
      return;
    }
    try {
      boot();
      if (rootDoc.getElementById(HOST_ID)) {
        console.info('[YU球] 已挂载 v' + VERSION + '（挂到' + (rootDoc === document ? '当前页面' : '父页面') + '）');
      }
    } catch (err) {
      console.error('[YU球] 启动失败', err);
    }
  }

  try {
    if (rootDoc && rootDoc.readyState === 'loading' && rootWin && typeof rootWin.addEventListener === 'function') {
      rootWin.addEventListener('DOMContentLoaded', () => start(), { once: true });
      setTimeout(start, 1500); // 兜底：DOMContentLoaded 已经错过了也要能起来
    } else {
      start();
    }
  } catch (err) {
    console.error('[YU球] 启动失败', err);
  }
})();
